insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 3', 'English Language', 'english', 'Oral Language', 'Songs', 'B3.1.1.1', 'Demonstrate understanding of a variety of songs', 'B3.1.1.1.1', 'Talk about the benefits of songs', 'Let learners identify some familiar songs e.g. patriotic songs such as ‘The National Anthem’.; Teach the songs identified, e. g. ‘The National Anthem’; Let learners sing rhythmically, using claps, gestures and dance where necessary.; Let learners, in convenient groups, identify and talk about the moral lessons in the songs.; Have learners think-pair-share the benefits of songs. Let the pairs then share their views with the whole class.', 10),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Rhymes', 'B3.1.2.1', 'Appreciate a variety of literary pieces', 'B3.1.2.1.1', 'Compose short rhymes and tongue-twisters and recite them', 'Revise some previously taught rhymes.; Present the new rhymes and perform them as learners listen and observe.; Read through the lines meaningfully with learners.; Let learners read through the lines in groups and individually on their own.; Focus on rhyming words by helping learners to identify them.; Put learners in convenient groups. Assign them a rhyme and task them to compose a parallel one.; Have groups recite their rhymes with the class.', 20),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B3.1.4.1', 'Respond to stories', 'B3.1.4.1.1', 'Respond to and ask questions based on stories heard', 'Select a suitable story to tell or read to the class. e.g. Ananse and the family.; Let learners tell their favourite parts of the story.; Have learners respond to the story by asking and answering relevant questions to enhance comprehension.', 30),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B3.1.4.1', 'Respond to stories', 'B3.1.4.1.2', 'Tell parallel stories', 'Select a suitable story to tell or read to learners, e.g. The old man.; Put learners into groups to compose a parallel story.; Let learners present their stories to the class for feedback.', 40),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B3.1.4.1', 'Respond to stories', 'B3.1.4.1.3', 'Create own events to extend stories heard', 'Let learners retell some stories they have read or heard. e.g. Ananse and the wisdom pot.; Pair up learners and have them create their own events to extend a story of their choice.; Invite representatives of the groups to share the part of the story they have created with the class.', 50),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Dramatisation and Role Play', 'B3.1.5.1', 'Perform stories', 'B3.1.5.1.1', 'Dramatise and role-play stories heard and read', 'Let learners mention titles of stories they have heard or read, e.g. The Magic Pot.; Let learners identify some characters in the stories mentioned.; Let learners dramatise or role-play stories they have heard, read or created, with appropriate characters.; Discuss stories dramatised or role-played.; Let learners comment on stories dramatised or role-played.', 60),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/ Cultural Values, Manners and other Themes', 'B3.1.6.1', 'Explore using certain culturally acceptable language for communication', 'B3.1.6.1.1', 'Use appropriate greetings for special occasions', 'Revise greetings for special occasions such as birthdays, anniversaries, festivals.; Let learners take turns to demonstrate greetings for special occasions and practise the appropriate responses.; Put learners into groups. Assign each group a special occasion for them to practise greetings and responses for that occasion.', 70),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/ Cultural Values, Manners and other Themes', 'B3.1.6.1', 'Explore using certain culturally acceptable language for communication', 'B3.1.6.1.2', 'Talk about events in the community', 'Have learners sing a familiar song about a topic.; Show pictures of events in the community, e.g. durbar, festival, naming ceremony, birthday.; Have learners think-pair-share the events with the person sitting next to them.; Have the pairs share their experiences with the class.; Have learners talk about which of the events they like most and why they like them.; Let learners, in groups, role-play the events of their choice.', 80),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/ Cultural Values, Manners and other Themes', 'B3.1.6.1', 'Explore using certain culturally acceptable language for communication', 'B3.1.6.1.3', 'Talk about important places in their communities', 'Show pictures of important places in their communities such as the community centre, the lorry station, the mission house, the market, the fire service station etc.; Let learners think-pair-share their views and opinions about the pictures.; Put learners into groups according to the number of pictures.; Have each group talk about the activities that go on in these places and their importance to the community and the nation.', 90),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/ Cultural Values, Manners and other Themes', 'B3.1.6.1', 'Explore using certain culturally acceptable language for communication', 'B3.1.6.1.4', 'Use a wider variety of words to talk about different customs and cultural values', 'Using conversational posters on different customs and cultural practices, let learners think-pair-share, looking at the various illustrations on the poster.; Have them use expressions learnt and other new ones to talk about the customs and cultural practices.; Let learners, in groups, role-play the customs and cultural practices on the poster.', 100),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/ Cultural Values, Manners and other Themes', 'B3.1.6.2', 'Apply knowledge of language and communicative skills to participate in conversation', 'B3.1.6.2.1', 'Demonstrate turn-taking in conversation in different topics', 'Let learners identify some familiar/interesting topics based on their environment for discussion.eg. Sanitation, Bush fires, Flooding, Pollution.; Let learners give scenarios from the identified topics.; Let learners demonstrate taking turns in conversations.; Guide appropriate language use in conversation.', 110),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/ Cultural Values, Manners and other Themes', 'B3.1.6.2', 'Apply knowledge of language and communicative skills to participate in conversation', 'B3.1.6.2.2', 'Ask and answer questions for clarification about what other people say', 'Revise topics previously discussed, e.g. Climate Change.; Ask questions on the topic discussed.; Let learners answer questions based on the topic discussed.; Guide and encourage learners to ask and answer questions for clarification on what other learners say.', 120),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/ Cultural Values, Manners and other Themes', 'B3.1.6.2', 'Apply knowledge of language and communicative skills to participate in conversation', 'B3.1.6.2.3', 'Participate in communication, using more varied and more accurate language', 'Put learners in groups. Have each group discuss the conversation posters on issues such as situations, events, customs, etc.', 130),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Places, Greetings, Customs, Events, Social/ Cultural Values, Manners and other Themes', 'B3.1.6.2', 'Apply knowledge of language and communicative skills to participate in conversation', 'B3.1.6.2.4', 'Express a greater variety of communicative meaning (', 'e.g. apologising, agreeing or disagreeing); Let learners role-play topics or themes discussed.; Discuss the importance of expressing a variety of communicative meanings/telling people about their feelings, etc.) e. g. apologising, agreeing or disagreeing with partners on issues.; Guide learners to express a variety of communicative meanings.', 140),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B3.1.7.1', 'Use appropriate skills and strategies to process meaning from texts B3.1.7.1: Use appropriate skills and strategies to process meaning from texts', 'B3.1.7.1.1', 'Listen to and interact actively within information texts Note: For all information text, use the KWL strategy. Below is the process', 'Before reading, let learners think- pair- share, and talk about what they already know (K) about the topic .Have learners ask questions about what they want to know (W).; While you read the text, pause often to give the children the chance to share what they have learned; Let learners answer the questions they asked before reading.; After the reading, have learners share what they have learned.', 150),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B3.1.7.1', 'Use appropriate skills and strategies to process meaning from texts B3.1.7.1: Use appropriate skills and strategies to process meaning from texts', 'B3.1.7.1.2', 'Recognise and relate the sequence of events in stories', 'Read a narrative text aloud to learners.; Put learners in groups to identify and talk about the parts of the story (e.g. beginning, middle and end).', 160),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B3.1.7.1', 'Use appropriate skills and strategies to process meaning from texts B3.1.7.1: Use appropriate skills and strategies to process meaning from texts', 'B3.1.7.1.3', 'Share facts from information texts heard with a partner, groups or the teacher', 'Read an information text aloud to learners using the KWL Strategy.  KWL Strategy: Before reading, have learners think-pair-share and talk about what they already know (K) about the title of the text. Have learners ask questions about what they want to know. (W). While you read the text, pause often to give the children the chance to share what they have learned or answer the questions they have asked before reading.; After the reading, have learners share what they have learned. Put learners in groups to share facts from the text heard.', 170),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions', 'B3.1.8.1', 'Demonstrate understanding in asking and answering questions', 'B3.1.8.1.1', 'Ask and answer questions for clarifications about given topics', 'Let learners select topics of interest for discussion.; Put learners in groups and have them ballot for topics.; Let members of each group discuss topics respecting rules of conversation.; Encourage learners to ask and answer questions for clarifications on issues raised in their discussion.', 180),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions', 'B3.1.8.1', 'Demonstrate understanding in asking and answering questions', 'B3.1.8.1.2', 'Use appropriate pronunciation and intonation in asking and answering the inversion questions', 'Let learners, in pairs, ask and answer questions on given issues.; Revise inversion questions with learners. e. g. He is going.—Is he going?; Guide learners to use appropriate pronunciation and intonation in asking and answering the inversion type of questions.; Let learners write answers to inversion type of questions on their own.', 190),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Giving and Responding to Commands/Instructions/Directions and Making Requests', 'B3.1.9.1', 'Demonstrate understanding in commands, instructions, directions and requests', 'B3.1.9.1.1', 'Give and respond to commands, instructions and directions A. Instructions Model giving instructions and ask learners to follow them', 'First, draw a square in the middle of your paper.; Next, draw a rectangle inside the square.; Then, draw an oval inside the rectangle. Response:; Pair up learners to practise giving and following instructions, e.g. giving and following instructions to clean the classroom. B. Directions Model giving directions and ask learners to follow them:; Show directions flash cards (go straight, turn left/right) and ensure learners understand the words. Place objects at different locations of the classroom.; Ask questions such as "Where is the book, pen, bag etc.? Then show the direction flash cards to help learners locate the items. Invite pairs of learners to practise giving and following directions. They can locate objects and places in the school.', 200),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Giving and Responding to Commands/Instructions/Directions and Making Requests', 'B3.1.9.1', 'Demonstrate understanding in commands, instructions, directions and requests', 'B3.1.9.1.2', 'Make and respond to polite requests', 'Show pictures of requests to learners and ask them to guess the requests from pictures: e.g. a picture of a closed door, a picture of an open door, a picture of someone carrying books etc. (Can you help me carry the books?, Please, close/open the door.); Invite pairs of learners to the front of the class to make and respond to polite requests. Let learner A pick a picture and Learner B make the request. Then, Learner A responds to the request made.; Have learners draw pictures of requests for their partners to guess the requests; Let learners practise making and accepting or declining requests using expressions such as "Yes, Of course, No problem, I''m sorry, I can''t, etc.', 210),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Presentation', 'B3.1.10.1', 'Plan and present information and ideas for a variety of purposes', 'B3.1.10.1.1', 'Present ideas logically', 'Discuss important people (e.g. teachers, footballers, farmer, police officer, etc.) in learners’ community and what made them important.; Ask learners to prepare presentations on what they would like to be important for and why.; Have learners present their work logically.', 220),
('Basic 3', 'English Language', 'english', 'Oral Language', 'Presentation', 'B3.1.10.1', 'Plan and present information and ideas for a variety of purposes', 'B3.1.10.1.2', 'Use appropriate verbal and non-verbal cues to convey meaning while speaking,', 'e.g. smiling, using gestures, etc; Demonstrate use of appropriate posture, verbal and non-verbal cues to communicate meaning, e.g. nodding, smiling, etc. to show approval.; Discuss the various non-verbal cues (e.g. facial expression, eye contact, crossed arms, etc.) you used and their meanings with learners.; Let the groups plan their presentations on an appropriate topic.; Give each group time to present and have the class talk about the appropriate verbal and non-verbal cues used.', 230),
('Basic 3', 'English Language', 'english', 'Reading', 'Phonics', 'B3.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B3.2.2.1.1', 'Understand the relationship between spelling of words and sounds of speech', 'Have learners revise writing out some words as you pronounce them. (You can also make them read words on the board or word cards).; Provide activities for learners to use letter names and sounds to spell and sound out words.', 240),
('Basic 3', 'English Language', 'english', 'Reading', 'Phonics', 'B3.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B3.2.2.1.2', 'Use the alphabetic knowledge to decode unknown words (', 'e.g. consonant blends, consonant digraphs, vowel sounds, vowel diagraphs and word patterns); Have learners sing an alphabet song.; Introduce consonant blends and digraphs, one at a time and have learners form words out of them and use them in sentences. Note: An important thing to remember is that a digraph is made of two letters, although the letters spell a sound e.g. bl, br, ch, ck, cl, cr, dr, fl, fr, gh, gl; Use the same procedure to teach vowel digraphs e. g. ai, ee, ea, ie, ei, oo, oe, oo, ue, oi, au', 250),
('Basic 3', 'English Language', 'english', 'Reading', 'Phonics', 'B3.2.2.1', 'Connect sounds to letters and blend letters/syllables in order to read and write', 'B3.2.2.1.3', 'Use basic elements of structural analysis (e.g prefixes, suffixes, compound, root words) to decode unknown words', 'Guide learners with examples to use the structure of words to decode.; Introduce words and have learners look for the parts. e.g. syllables, prefixes and suffixes.; Let learners identify words with similar parts/structures.', 260),
('Basic 3', 'English Language', 'english', 'Reading', 'Word Families-Rhyming Endings and Common Digraphs', 'B3.2.3.1', 'Employ knowledge of rhyming endings and common digraphsto enhance reading comprehension', 'B3.2.3.1.1', 'Use common rhyming/endings words for decoding of words', 'Introduce learners to simple word formation by changing the beginning letter. e.g. pin, sin, fin; Have learners build on these rhyming endings and read out the words to their group members.; Have learners form sentences with these rhyming words.', 270),
('Basic 3', 'English Language', 'english', 'Reading', 'Word Families-Rhyming Endings and Common Digraphs', 'B3.2.3.1', 'Employ knowledge of rhyming endings and common digraphsto enhance reading comprehension', 'B3.2.3.1.2', 'Use words containing digraphs to make meaningful sentences', 'Introduce learners to simple digraphs as in: sh- shirt ch- church gh- Ghana ph-phone; Have learners build as many words as possible with the digraphs and form meaningful sentences with some of the words.', 280),
('Basic 3', 'English Language', 'english', 'Reading', 'Diphthongs', 'B3.2.4.1', 'Show understanding of diphthongs', 'B3.2.4.1.1', 'Use diphthongs to build words', 'Revise digraphs and have learners identify them in words.; Introduce diphthongs in context. e.g. ou-out, loud, cloud; Through think-pair-share, let learners generate diphthongs and build words with them.', 290),
('Basic 3', 'English Language', 'english', 'Reading', 'Blends and Consonant Clusters', 'B3.2.5.1', 'Identify and use consonant blends in words', 'B3.2.5.1.1', 'Use consonant blends to build words', 'Have learners revise diphthongs and use them in sentences.; Introduce consonant blends and have learners identify words having the blends. e.g. bl - black br- brush st- stone tr- tree; Let learners work in pairs/groups to identify consonant blends and build words from them.', 300),
('Basic 3', 'English Language', 'english', 'Reading', 'Vocabulary', 'B3.2.6.1', 'Understand word meanings and usage', 'B3.2.6.1.1', 'Read level-appropriate sight words, understand and use them in meaningful complex sentences', 'Provide learners with texts containing level-appropriate sight words.; Put them into groups to identify, read and use sight words in meaningful sentences.', 310),
('Basic 3', 'English Language', 'english', 'Reading', 'Vocabulary', 'B3.2.6.1', 'Understand word meanings and usage', 'B3.2.6.1.2', 'Use knowledge of prefixes and suffixes to interpret unfamiliar words', null, 320),
('Basic 3', 'English Language', 'english', 'Reading', 'Vocabulary', 'B3.2.6.1', 'Understand word meanings and usage', 'B3.2.6.1.3', 'Understand and use many of the frequently occurring words and chunks in the language, including both content words (nouns, verbs, adjectives and adverbs) and function words ( prepositions, articles)', 'Revise learners RPK by asking them to use some sight words learnt in earlier lessons.; Introduce new words and have learners form sentences with them as you guide them with simple ways to find contextual meanings of words.; You may introduce game activities e.g. Lucky Dip to provide practice in identification and use of sight words.', 330),
('Basic 3', 'English Language', 'english', 'Reading', 'Vocabulary', 'B3.2.6.1', 'Understand word meanings and usage', 'B3.2.6.1.4', 'Use dictionaries, glossaries and internet to clarify word meanings', 'Introduce learners to the dictionary and glossaries.; Have learners find the dictionary meaning to key words in a comprehension passage.; Have learners make or build their own glossaries on the words learnt.; In groups, let learners practise finding key words and building their own word albums/dictionaries/glossaries.', 340),
('Basic 3', 'English Language', 'english', 'Reading', 'Comprehension', 'B3.2.7.1', 'Understand and analyse texts read', 'B3.2.7.1.1', 'Use self-correction strategies to make meaning when reading texts', 'Engage learners on before reading activities, e.g. review of background knowledge, discussion of title and accompanying pictures).; Model reading the text aloud and have learners echo-read the text (if necessary).; Read out words and sentences for learners to identify in the text.; Let learners read aloud in groups and pairs and answer questions.', 350),
('Basic 3', 'English Language', 'english', 'Reading', 'Comprehension', 'B3.2.7.1', 'Understand and analyse texts read', 'B3.2.7.1.2', 'Ask and answer factual, inferential and vocabulary questions about level-appropriate texts', 'Have learners brainstorm on the topic on which they will answer questions.; Ask learners to read and answer simple pre-reading questions as you guide them.; Guide learners to ask and answer factual, inferential and vocabulary questions on the passage read.', 360),
('Basic 3', 'English Language', 'english', 'Reading', 'Comprehension', 'B3.2.7.1', 'Understand and analyse texts read', 'B3.2.7.1.3', 'Retell level-appropriate text in own, explain and illustrate', 'Ask a few questions to review the text/story to be retold.; Have learners narrate or retell the story passage using the herring bone or story map strategy. The narration should be sequential to make the story understood.', 370),
('Basic 3', 'English Language', 'english', 'Reading', 'Comprehension', 'B3.2.7.2', 'Use knowledge, skills and techniques of reading to understand, interpret and appreciate a variety of literary texts', 'B3.2.7.2.1', 'Demonstrate understanding of the purpose and features of poems or rhymes and fables, etc', 'Introduce the lesson with before reading activities, singing, reciting, prediction, etc.; Have learners read a text and identify its purpose and features. Guide them with questions to do this.; Let learners transfer the same ideas to other types of texts.; Use think-pair-share to have learners compare ideas.', 380),
('Basic 3', 'English Language', 'english', 'Reading', 'Comprehension', 'B3.2.7.2', 'Use knowledge, skills and techniques of reading to understand, interpret and appreciate a variety of literary texts', 'B3.2.7.2.2', 'Respond to stories with own opinion and value judgment', 'Have learners give their personal opinions and judgment to stories (events, setting, characters and their actions) read or heard.', 390),
('Basic 3', 'English Language', 'english', 'Reading', 'Comprehension', 'B3.2.7.2', 'Use knowledge, skills and techniques of reading to understand, interpret and appreciate a variety of literary texts', 'B3.2.7.2.3', 'Use visualisation strategy (form mental images when reading text) to enhance understanding of level-appropriate texts', 'Have learners play simple mental or guessing games like Bingo and matching games.; Guide learners to form mental images as they read a text, to help them make meaning from the text.', 400),
('Basic 3', 'English Language', 'english', 'Reading', 'Comprehension', 'B3.2.7.2', 'Use knowledge, skills and techniques of reading to understand, interpret and appreciate a variety of literary texts', 'B3.2.7.2.4', 'Read level-appropriate texts independently', 'Provide learners with level-appropriate texts and encourage them to read independently.; Let learners may be provided with pre-reading questions to enable them focus.', 410),
('Basic 3', 'English Language', 'english', 'Reading', 'Fluency', 'B3.2.9.1', 'Read texts fluently', 'B3.2.9.1.1', 'Read long texts with good pace, accuracy and expression', 'Engage learners in pre-reading and demonstrate/model reading aloud with fluency, accuracy and expression.; Have learners practise in pairs and groups. Note: Learners must read at their own pace.', 420),
('Basic 3', 'English Language', 'english', 'Reading', 'Fluency', 'B3.2.9.1', 'Read texts fluently', 'B3.2.9.1.2', 'Recognise more than two hundred high frequency words with automaticity', 'Revise the knowledge of sight words through games.; Have learners identify sight words in texts using games such as Fishing and Lucky Dip.; Let learners use the sight words to construct meaningful sentences.', 430),
('Basic 3', 'English Language', 'english', 'Reading', 'Fluency', 'B3.2.9.1', 'Read texts fluently', 'B3.2.9.1.3', 'Use self-correction strategy to make meaning from texts (repeated)', 'Have learners use self-correction strategy as they pronounce words in a read aloud lesson.; Check for intonation and pace as they read to make meaning.', 440),
('Basic 3', 'English Language', 'english', 'Writing', 'Persuasive/Argumentative Writing', 'B3.3.13.1', 'Support an opinion in writing', 'B3.3.13.1.1', 'Write a short paragraph to support an opinion or claims with clear reasons', 'Choose a simple topic for an argument. e.g. Which food is better; rice or fufu? (It could be any food, depending on learners’ background.); Let learners choose one of the meals and give reasons why they think it is better.; Put the class into two to argue on the topic.', 450),
('Basic 3', 'English Language', 'english', 'Writing', 'Penmanship/Handwriting', 'B3.4.2.1', 'Copy and write sentences correctly', 'B3.4.2.1.1', 'Copy short paragraphs clearly', 'Model copying a short paragraph on the board drawing attention to features such as clarity, spacing and alignment of letters.; Let learners practise copying a short paragraph legibly and correctly on the board.; Have learners copy short paragraphs from a book into their exercise books.', 460),
('Basic 3', 'English Language', 'english', 'Writing', 'Writing /Copying Letters – Small and Capital', 'B3.4.3.1', 'Use general skills, strategies and knowledge of letter- sounds to write legibly and boldly', 'B3.4.3.1.1', 'Use letter-sound relationships to represent most letters in words correctly', 'Let learners play the alphabet sound game.; Dictate words and simple sentences for learners to write.', 470),
('Basic 3', 'English Language', 'english', 'Writing', 'Labelling items', 'B3.4.4.1', 'Draw and label simple pictures', 'B3.4.4.1.1', 'Make a list of objects found in the environment', 'Lead the class to make a list of objects found in a given thematic area. e.g. The Bus Stop.; Let groups and pairs make similar lists from self-chosen or given areas. They may use invented spelling initially.; Guide learners to edit and self-correct the errors before presenting their work to the class. They may use children’s pictures, dictionaries and other sources.', 480),
('Basic 3', 'English Language', 'english', 'Writing', 'Writing Simple Words and Sentences', 'B3.4.5.1', 'Write accurately using acquired vocabulary and knowledge of grammar', 'B3.4.5.1.1', 'Write simple sentences to express personal opinions about favourite characters in texts', 'Put learners in groups to discuss characters in a story read.; Have learners write simple sentences to express personal opinions on favourite characters.; Let learners exchange their books and do peer editing by checking for: i. correct spelling of words, ii. correct writing of capitals, iii. correct writing of small letters, iv. correct spacing of letters and words.', 490),
('Basic 3', 'English Language', 'english', 'Writing', 'Writing Simple Words and Sentences', 'B3.4.5.1', 'Write accurately using acquired vocabulary and knowledge of grammar', 'B3.4.5.1.2', 'Write simple meaningful sentences to express feelings and opinions about people and things', 'Guide learners, with examples, to write simple sentences to express their feelings and opinions about their peers and things found in the environment.; Have the groups edit their work and publish them.', 500),
('Basic 3', 'English Language', 'english', 'Writing', 'Writing Simple Words and Sentences', 'B3.4.5.1', 'Write accurately using acquired vocabulary and knowledge of grammar', 'B3.4.5.1.3', 'Draw pictures and write, at least, three sentences to share an opinion', 'Show the images/‘smileys’ on a mobile phone.; Working in groups, let learners use the computer to search for these smiley/images. (The ICT teacher can guide learners by showing the appropriate icon to help them explore these).; Have learners draw their own pictures and write sentences to explain them. e.g. a drawing showing fruits can have a sentence such as “Eat fruits every day; Fruits have vitamin C; Fruits protect your body.”; Guide learners to do self and peer editing (The products can be transferred on to a manila card and posted on the walls in the classroom) to be appreciated and critiqued.', 510),
('Basic 3', 'English Language', 'english', 'Writing', 'Writing Simple Words and Sentences', 'B3.4.5.1', 'Write accurately using acquired vocabulary and knowledge of grammar', 'B3.4.5.1.4', 'Copy various sentences, verses and words of songs legibly (writing should be bold and clear)', 'Explain the writing activity selected, stressing the need for accuracy, clarity, etc.; As learners observe, demonstrate it.; Assign them to do the exercise. They may copy from the board and books.; Provide feedback after assessing learners’ work.', 520),
('Basic 3', 'English Language', 'english', 'Writing', 'Guided Composition', 'B3.4.8.1', 'Compose short paragraphs through answering questions', 'B3.4.8.1.1', 'Develop two coherent paragraphs on one idea or concept using leading questions', 'Have learners brainstorm to choose a topic, e. g. My home; Write the topic on the board.; Ask questions for learners to generate ideas on the topic; Discuss the questions with learners for them to answer appropriately e.g. My home i. Where do you live? ii. How many of you live there? iii. What kind of buildings are there?', 530),
('Basic 3', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B3.4.9.1', 'Apply the skills and strategies for idea generation, selection, development, organization and revision in writing', 'B3.4.9.1.1', 'Select a topic on familiar themes (', 'e.g. Myself), brainstorm and organise before writing Take learners through the writing process: Pre-writing stage; Consider composition writing as a process. That is, it should be done in stages.; Take learners through stages such as preparation, writing, editing and publishing.; Assist learners to prepare for writing by discussing the topic to write on, e.g. My school.; In groups, let learners discuss their ideas.; Use learner strategies such as brainstorming to help learners generate ideas appropriate to the topic.', 540),
('Basic 3', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B3.4.9.2', 'Develop and express ideas coherently and cohesively in writing', 'B3.4.9.2.1', 'Write ideas on a topic in simple sentences Writing stage', 'Have learners write their first draft in groups.; Let learners write their ideas as they appear, without taking particular note of corrections or editing.; Let learners add on new ideas that occur to them as they write.', 550),
('Basic 3', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B3.4.9.3', 'Apply strategies for improving drafts for publishing', 'B3.4.9.3.1', 'Review and revise the draft, adding to or taking out ideas', 'In groups, have learners revise their writing paying attention to little details.; Have learners use these questions as a revision guide: i. Is my topic interesting? ii. Does the beginning catch the reader’s attention? iii. Are the ideas easy to understand? iv. Are all the sentences saying something about the topic?; Encourage learners to make as many changes as necessary to improve their work.', 560),
('Basic 3', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B3.4.9.3', 'Apply strategies for improving drafts for publishing', 'B3.4.9.3.2', 'Proofread draft to correct punctuation and spelling errors', 'Have learners proofread the revised draft of their writing for errors relating to the conventions of punctuation, capitalization, spelling, etc.; Have learners check their editing through CUPS: C- Capitalisation U- language Usage P- Punctuation S- Spelling; Let learners do peer editing: learners check their partners’ writing for punctuation and spelling errors.; Have learners write a neat final copy and read it once again to check for errors.', 570),
('Basic 3', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B3.4.9.3', 'Apply strategies for improving drafts for publishing', 'B3.4.9.3.3', 'Read aloud own writing to a group or whole class', 'Have learners publish their work by showing it to others in small groups or in pairs or posting it on the class or school notice board for others to view.', 580),
('Basic 3', 'English Language', 'english', 'Writing', 'Narrative Writing', 'B3.4.10.1', 'Narrate situations, express feelings and convey point of view about the world/fictional world', 'B3.4.10.1.1', 'Add more details of a story structure to narrative stories,', 'for example setting, characters, problem and resolution of the problem; Read a short narrative story to learners; concentrate on the setting and the characters.; Let learners narrate their experiences.; Assist learners to pick a topic. e. g. The traffic light.; Let learners write on the topic, narrating their experience. E.g. On my way to school, I crossed the road. I looked left, right and left again. There was no vehicle coming. Then I walked quickly across the road.', 590),
('Basic 3', 'English Language', 'english', 'Writing', 'Narrative Writing', 'B3.4.10.1', 'Narrate situations, express feelings and convey point of view about the world/fictional world', 'B3.4.10.1.2', 'Engage and orient the reader by establishing a context and introducing a narrative', 'Narrate a story stressing the setting and the characters for learners to listen.; Let learners re-tell the story. They may do so in a chain, Let learners create and write their own stories.', 600),
('Basic 3', 'English Language', 'english', 'Writing', 'Descriptive Writing', 'B3.4.12.1', 'Demonstrate knowledge of description of writing', 'B3.4.12.1.1', 'Describe places in a coherent paragraph', 'Have learners recall periods, times or moments that they had been happy or sad.; Discuss personal experiences with learners.; Guide them to state categorically some personal experiences they have encountered in their lives.; Have learners share their experiences using simple descriptive words.; Discuss lessons learnt from the experiences shared.; Have learners write experiences shared logically and sequentially. e.g. about interesting places they have visited.', 610),
('Basic 3', 'English Language', 'english', 'Writing', 'Informative/ Academic Writing', 'B3.4.14.1', 'Write on the events of the day', 'B3.4.14.1.1', 'Write picture events using simple sentences', 'Using dictionaries and modelling, guide learners to give information on events of the day to their partners, class /groups/partners.; Have learners represent this in the form of a picture.; Have learners write simple sentences to accompany the pictures.; Have learners share their work with the class. Note: (Give room for positive appreciation).', 620),
('Basic 3', 'English Language', 'english', 'Writing', 'Informative/ Academic Writing', 'B3.4.14.1', 'Write on the events of the day', 'B3.4.14.1.2', 'Make a radio/TV presentations/performances', 'Let Learners rehearse presenting information on radio or TV.; Have learners generate ideas, plan and present them in groups as done on radio.; Assign groups to present their ideas to the whole class.; Plan for a live presentation/performance.', 630),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Capitalisation', 'B3.5.1.1', 'Apply knowledge of capitalisation in writing', 'B3.5.1.1.1', 'Use capital letters to write initials and abbreviations', 'Introduce initials and abbreviations in context.; Provide learners with sentences or texts containing initials and abbreviations for them to identify. e. g. WHO – World Health Organisation; K. S. Manu – Kofi Sakyi Manu; Give texts having full names of people and organisations.; Ask learners to rewrite the text and replace the full names of people and organisations with initials and abbreviations.', 640),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Capitalisation', 'B3.5.1.1', 'Apply knowledge of capitalisation in writing', 'B3.5.1.1.2', 'Demonstrate the ability to capitalise titles of texts', 'Provide sample varied stories and passages whose titles or headings have capital letters at the beginning of content words, e.g. “Ananse and the Wisdom Pot".; Put learners into groups to study the titles/headings and discover the use of capital letters in context.; Have groups present their observations.; Give learners titles/headings of stories or texts in lower case for them to re-write using capital letters at the beginning of content words.', 650),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Punctuation', 'B3.5.2.1', 'Apply knowledge of the use of punctuation in communication', 'B3.5.2.1.1', 'Use full stops in initials and abbreviations', 'Revise the use of the full stop (.).; Provide a short passage of about four sentences.; Pair learners place a full stop at the end of each sentence.; Introduce full stops in initials and abbreviations. e.g. Mr. Badu - Mister Badu, A. O. Boateng – Adom Opoku Boateng; Provide opportunities for learners to practise using full stops in initials of their names, and abbreviations.', 660),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Punctuation', 'B3.5.2.1', 'Apply knowledge of the use of punctuation in communication', 'B3.5.2.1.2', 'Use commas appropriately to list items', 'Help learners to separate items in a list, using commas, e.g. My friend has a pen, pencil, eraser and a book.', 670),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Punctuation', 'B3.5.2.1', 'Apply knowledge of the use of punctuation in communication', 'B3.5.2.1.3', 'Identify and use the apostrophe to show possession', 'Introduce the apostrophe showing possession in context. e.g. Kofi''s mother has travelled.', 680),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Action Words', 'B3.5.4.1', 'Apply knowledge of action words in communication B3.5.4.1.3', 'B3.5.4.1.1', 'Identify the present continuous form of action words in spoken and written communication', 'Through demonstration, assist learners to use the continuous form of the action words such as running, eating and sitting. Provide sentences and let learners identify the continuous form of the action words: e.g. Adongo is running with the ball.', 690),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Action Words', 'B3.5.4.1', 'Apply knowledge of action words in communication B3.5.4.1.3', 'B3.5.4.1.2', 'Use the present continuous form of verbs to describe actions taking place at the time of speaking', 'Through examples, assist learners to use the continuous forms of action words in sentences. e.g. Aba is singing. They are jumping.; Present action pictures for learners to write simple sentences about the actions taking place.', 700),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Action Words', 'B3.5.4.1', 'Apply knowledge of action words in communication B3.5.4.1.3', 'B3.5.4.1.3', 'Use simple past and the past continuous forms of verbs to express past actions', 'Revise the use of the present simple and present continuous tenses.; Introduce the new form, one at a time, using examples and situations.; Provide examples for practice through drills and creation of situations.', 710),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Qualifying Words –Adjectives', 'B3.5.5.1', 'Apply knowledge of adjectives in communication', 'B3.5.5.1.1', 'Identify and use adjectives in short sentences to describe height, length, etc', 'Provide sentences with simple adjectives for learners to identify, e.g. I saw a tall tree.; Put learners in groups to use the adjectives identified in simple sentences.', 720),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Qualifying Words – Adverbs', 'B3.5.6.1', 'Show understanding of adverbs in communication', 'B3.5.6.1.1', 'Identify qualifying words', 'Provide sentences with simple adverbs for learners to identify. e.g. i. He walked quickly to the church. ii. She danced beautifully.; Elicit other adverbs and provide practice.', 730),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Qualifying Words – Adverbs', 'B3.5.6.1', 'Show understanding of adverbs in communication', 'B3.5.6.1.2', 'Use adverbs correctly to express time, frequency, etc', 'Guide learners with examples and situations to use adverbs of time and frequency.', 740),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Simple Prepositions', 'B3.5.7.1', 'Apply the knowledge of simple prepositions in oral and written communication', 'B3.5.7.1.1', 'Identify prepositions in sentences to indicate directions and means,', 'e.g. by bus; Provide sample sentences. e.g. means -We are going home by bus. direction - The monkey is climbing up the tree.; Guide learners to discover the meaning of the sentences.; Draw learners’ attention to the words as prepositions.; Have learners complete sentences with given prepositions that indicate means and direction. e.g. Mr. Badu is travelling ________ train.', 750),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Using Simple and Compound Sentences', 'B3.5.9.1', 'Demonstrate understanding of compound sentences in writing', 'B3.5.9.1.1', 'Identify and use coordinating conjunctions to join similar ideas or contrasting ideas in sentences', 'Demonstrate the structure of a compound sentence by joining simple sentences with and. e.g. simple sentences Conjunction compound sentence The boy woke up. The boy woke up and The boy prayed. And prayed.; Have learners identify the coordinating conjunction in the sentence.; Put learners in groups to form simple sentences.; Have groups join the simple sentences with and and but.; Conjunction; And', 760),
('Basic 3', 'English Language', 'english', 'Using Writing Conventions/Grammar Usage', 'Spelling', 'B3.5.10.1', 'Use phonics knowledge to spell words', 'B3.5.10.1.1', 'Spell phonically irregular words correctly', 'Have learners play the Pick and Spell game to spell phonically irregular words. e. g. enough, answer, because, bought.; Dictate the words for learners to spell.; Have learners use these words in oral and written sentences.; Provide sentences with blank spaces for learners to fill in the blanks using the words they have learnt to spell. e.g. bought, answer, because, enough etc. ii. I drink ------- water. iii. Your ................. is wrong. iv. I miss the class ..................... I was late. v. My father ................... chocolate.', 770),
('Basic 3', 'English Language', 'english', 'Extensive Reading', 'Building the Love and Culture of Reading', 'B3.6.1.1', 'Read widely for pleasure and demonstrate independent reading and learning in the literary area', 'B3.6.1.1.1', 'Read a variety of age and level-appropriate books and summarise them', 'Using the Author’s chair, introduce the reading/library time.; Have a variety of age/level-appropriate books for learners to make a choice from.; Introduce narratives, expository, procedural texts to learners.; Guide learners to select books for readings', 780),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Songs', 'B3.1.1.1', 'Demonstrate an understanding of some selected songs by telling what the songs are about', 'B3.1.1.1.1', 'Sing songs with the correct rhythms and discuss the meaning and moral values of the song', 'Let learners sing a familiar occupational song they know.; Play familiar traditional songs on a tape/clip for learners to listen.; Teach learners the song and let them sing the song alone.; Allow learners to sing the song with correct rhythms.; Lead learners to brainstorm the meaning of the song.; Lead learners through discussion to tell the moral values in the song.', 10),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Rhymes', 'B3.1.2.1', 'Show an understanding of some rhymes', 'B3.1.2.1.1', 'Recognise rhyming words', 'Let learners sing a popular play song they know.; Read aloud a rhyme to learners.; Let learners read aloud the rhyme in turns.; Lead learners through discussions to recognise rhyming words in the rhyme.', 20),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Rhymes', 'B3.1.2.1', 'Show an understanding of some rhymes', 'B3.1.2.1.2', 'Produce own rhyming words', 'Let learners sing a popular work song they know.; Write your own rhyme and read it to the learners.; Lead learners to read the rhyme in turns.; Discuss the skills involved in writing a rhyme with learners.; Encourage learners to produce their own rhyming words.', 30),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Poems', 'B3.1.3.1', 'Demonstrate knowledge of poem recitation with the correct stress and rhythm by listening attentively', 'B3.1.3.1.1', 'Explore poems and note the words and discuss what the poem is about', 'Explore poems to learners.; As you read the poem, allow them to note words in the poem.; Let learners explore poems and take note of the words.; Lead learners to explore the poem with gestures.; Let learners tell what the poem is about.', 40),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B3.1.4.1', 'Exhibit knowledge of listening to and reading simple and interesting stories', 'B3.1.4.1.1', 'Mention some of the key words in a story', 'Revise occupational songs with learners.; Tell/show an interesting story.; Discuss the story with learners.; Help learners to mention some of the key words in the story.', 50),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B3.1.4.1', 'Exhibit knowledge of listening to and reading simple and interesting stories', 'B3.1.4.1.2', 'Mention issues and morals in a story', 'Let learners sing a song they know.; Tell/show an interesting story.; Discuss the setting of the story with learners.; Help learners to mention issues and morals in the stories.', 60),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B3.1.4.1', 'Exhibit knowledge of listening to and reading simple and interesting stories', 'B3.1.4.1.3', 'Dramatise the story', 'Let learners demonstrate an occasional greeting in pairs.; Lead learners to sing a popular traditional song.; Tell/play an interesting story.; Discuss the story with learners.; Assign roles to learners.; Direct learners to dramatise the story.', 70),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Dramatisation and Role Play', 'B3.1.5.1', 'Perform a sketch of a story heard, told or read', 'B3.1.5.1.1', 'Give details of characters and costumes for a drama', 'Lead learners to sing a song.; Tell or read an interesting story to learners.; Discuss the story with learners and assign roles to them.; Direct learners to role play the story.; Lead learners to discuss details of characters and costumes for the drama.', 80),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Dramatisation and Role Play', 'B3.1.5.1', 'Perform a sketch of a story heard, told or read', 'B3.1.5.1.2', 'State opinion and feelings on events and characters in stories', 'Let learners sing a popular song they know.; Tell or read an interesting story to learners.; Help the learners to state their opinions and feelings on events and characters in the story.', 90),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B3.1.6.1', 'Exhibit an understanding of appropriate non-formal forms of greeting and communication', 'B3.1.6.1.1', 'Discuss and demonstrate non-verbal forms of greeting', 'Revise greetings with learners.; Demonstrate some non-verbal forms of greetings for learners to see.; Let learners recognise the various non-verbal forms of greetings. E.g. Handshake, gestures for greeting and nodding of the head.; Allow learners to demonstrate the various non-verbal forms of greetings in groups and in pairs.', 100),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B3.1.6.1', 'Exhibit an understanding of appropriate non-formal forms of greeting and communication', 'B3.1.6.1.3', 'Say why we have non-verbal greetings', 'Discuss with learners why we use non-verbal forms to greet.', 110),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B3.1.7.1', 'Apply the use of pronouns appropriately in simple sentences', 'B3.1.7.1.1', 'Describe one’s self using personal pronouns', 'Let learners say the letters of the alphabet.; Write some words on the board and lead learners to say the words.; Let learners form sentences with the words.; Introduce pronoun to learners.; Let learners describe themselves using personal pronouns. E.g. I, me, mine.', 120),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B3.1.7.1', 'Apply the use of pronouns appropriately in simple sentences', 'B3.1.7.1.2', 'Describe the family using the appropriate pronouns', 'Use pronouns to talk about a family.; Let learners describe their families using the appropriate pronouns.', 130),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening Comprehension', 'B3.1.8.1', 'Show an understanding of answering questions from a passage', 'B3.1.8.1.1', 'Recount what the story is about and answer simple questions on the story', 'Lead learners to sing a song.; Tell/show an interesting story.; Discuss the story with learners.; Lead learners to discuss what the story is about.; Ask questions based on the story for learners to answer.', 140),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening Comprehension', 'B3.1.8.1', 'Show an understanding of answering questions from a passage', 'B3.1.8.1.2', 'Explain the meaning of key words and give simple summary of a short text', 'Lead learners to sing a song.; Read a story.; Let learners read the story as a group and in turns.; Write the key words in the story on the board.; Use keywords from the story in different contexts.; Let learners also use the key words to form sentences.; Allow learners to give contextual meaning of some key words.; Give a summary of the text read.; Let learners read the text again.; Group learners and encourage them to write a simple summary of the short text.', 150),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B3.1.9.1', 'Demonstrate knowledge on understanding and answering of questions correctly by the use of question words', 'B3.1.9.1.1', 'Answer questions on, ‘who”, “what”, “where” and” when”', 'Let learners say the letters of the alphabet.; Write the question words on flashcards.; Lead learners to read the question words.; Use the question words to form questions and lead learners to read.; Use the flashcards to assist learners to recognise when to use question words. “what”, “who”,” where”,” when”.; Let learners form their own questions using the question words discussed.', 160),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B3.1.9.1', 'Demonstrate knowledge on understanding and answering of questions correctly by the use of question words', 'B3.1.9.1.2', 'Recognise and tell when to use the question words “how” and “why”', 'Let learners say the letters of the alphabet.; Write the question words on flashcards.; Lead learners to read the question words.; Use the question words to form questions and lead learners to read.; Use the flashcards to assist learners to recognise when to use question words “how” and “why”.', 170),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B3.1.9.1', 'Demonstrate knowledge on understanding and answering of questions correctly by the use of question words', 'B3.1.9.1.3', 'Answer and ask ‘who”, “what”, “where”, “when”, “how” and “why” questions', 'Let learners say the letters of the alphabet.; Write the question words on flashcards.; Lead learners to read the question words.; Use the question words to form questions and lead learners to read.; Use the flashcards to assist learners to recognise when to use question words.; Write questions using the question words ‘what’, ‘when and ‘how’ and ‘why’ on the board.; Lead learners to read the questions.; Let learners read the questions in turns.; Help learners to recognise when to use question word “why”.; Let learners form their own questions using the question word “why.”', 180),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B3.1.10.1', 'Exhibit knowledge of understanding and listening attentively to simple instructions and directions and carrying them out', 'B3.1.10.1.1', 'Understand instructions and carry them out', 'Let learners say the letters of the alphabet.; Instruct some learners to issue an instruction for the rest to carry out the instruction.; Let learners discuss and understand instructions and carry them out.', 190),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B3.1.10.1', 'Exhibit knowledge of understanding and listening attentively to simple instructions and directions and carrying them out', 'B3.1.10.1.2', 'Understand directions and carry them out', 'Let learners say the letters of the alphabet.; Direct some learners to a given place in the school.; Let learners discuss directions, understand and follow directions.', 200),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B3.1.10.1', 'Exhibit knowledge of understanding and listening attentively to simple instructions and directions and carrying them out', 'B3.1.10.1.3', 'Give directions accurately', 'Direct some learners to a given place in the school.; Help learners to give directions accurately to that place.', 210),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B3.1.11.1', 'Demonstrate knowledge on the days of the week and say the time by the hour and minutes', 'B3.1.11.1.1', 'Say the time by the hour and half hour', 'Show a clock to learners.; Discuss the use of a clock with learners.; Introduce the hour and minute hands to learners.; Discuss the functions of the hour and minutes hands with learners.; Help learners to tell time by the hour and half hour. E.g. The time is 9 o’clock. The time is 9:30', 220),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B3.1.11.1', 'Demonstrate knowledge on the days of the week and say the time by the hour and minutes', 'B3.1.11.1.2', 'Say the time by the hour and minutes', 'Show a clock to learners and discuss its function with them.; Revise the functions of the hour and minutes hands with learners.; Help learners to tell time by the hour and minute. E.g. The time is 9:30. The time is 9:15. B3.1.1.3 Say the days of the week and names associated with the days.; Lead learners to explore a rhyme with gestures.; Write the names of days of the week on flashcards.; Lead learners to read the names of the days of the week.; Use the flashcards to help learners to recognise names associated with the days of the week. E.g. Monday, Tuesday, etc.', 230),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B3.2.2.1', 'Show an understanding of connecting sounds to letters and blending letters into syllables in order to read', 'B3.2.2.1.3', 'Read simple short sentences that include compound word', 'Let learners say the letters of the alphabet.; Write and read simple short sentences that include compound words on the board.; Lead learners to read the sentences aloud.; Underline the compound words in the sentences and encourage learners to use the words to form simple short sentences that include compound words.', 240),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonological and Phonemic Awareness', 'B3.2.3.1', 'Demonstrate knowledge of listening, recognising and differentiating sounds in spoken words', 'B3.2.3.1.1', 'Recognise and separate syllables', 'Lead learners to say the letters of the alphabet as a group.; Call learners to say the letters of the alphabet in turns.; Practice syllable recognition and separation with learners on the board.; Allow learners to apply the knowledge to recognise and separate syllables in words.', 250),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonological and Phonemic Awareness', 'B3.2.3.1', 'Demonstrate knowledge of listening, recognising and differentiating sounds in spoken words', 'B3.2.3.1.2', 'Add individual sounds in simple one-syllable words to make up new words', 'Lead learners to say the letters of the alphabet as a group.; Call learners to say the letters of the alphabet in turns.; Practice adding individual sounds to one syllabic words.; Encourage learners to add sounds to one-syllabic words to form new words on their own. E.g. /ba/ + /g/ = bag /ba/ + /t/ = bat', 260),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonological and Phonemic Awareness', 'B3.2.3.1', 'Demonstrate knowledge of listening, recognising and differentiating sounds in spoken words', 'B3.2.3.1.3', 'Substitute one sound in two-syllable words to make up new words', 'Lead learners to say the letters of the alphabet as a group.; Call learners to say the letters of the alphabet in turns.; Demonstrate adding one sound to two-syllabic words to form new words on the board.; Let learners apply the knowledge to substitute one sound in two- syllable words to make up new words. E.g. /table/ -/t/ + /c/ = /cable/ /carrot/ - /c/ + /p/ = /parrot/ /toffee/ -/t/ + /c/=/coffee/', 270),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B3.2.4.1', 'Show an understanding of connecting sounds to letters and blending letters into syllables in order to read', 'B3.2.4.1.1', 'Use alphabetic awareness to decode words', 'Lead learners to say the letters of the alphabet as a group.; Call learners to say the letters of the alphabet in turns.; Practice alphabetic awareness to decode words on the board for learners to observe.; Aid learners to use alphabetic awareness to decode simple words.', 280),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B3.2.4.1', 'Show an understanding of connecting sounds to letters and blending letters into syllables in order to read', 'B3.2.4.1.2', 'Use alphabetic awareness to decode compound words', 'Let learners say the letters of the alphabet as a group and individually.; Practice alphabetic awareness with learners to decode compound words on the board.; Assist learners to use alphabetic awareness to decode compound words.', 290),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B3.2.4.2', 'Recognise and read words with identical sounds', 'B3.2.4.2.1', 'Listen and say words with identical sounds from poems', 'Let learners explore a rhyme they know.; Read poems to learners.; Ask learners to listen attentively and pick words with identical sounds.; Let learners say the words with identical sounds from the poem.; Let learners use the words to form their own sentences.', 300),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B3.2.4.2', 'Recognise and read words with identical sounds', 'B3.2.4.2.2', 'Read poems and recognise rhyming words', 'Let learners explore a rhyme they know.; Read or play a poem to learners.; Lead learners through discussions to recognise the rhyming words in the poem.; Ask learners to explore the poem and recognise rhyming words from the poem.', 310),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B3.2.4.2', 'Recognise and read words with identical sounds', 'B3.2.4.2.3', 'Read two-syllable words', 'Let learners say the letters of the alphabet.; Form one-syllable words and lead learners to say the words.; Join two of the one-syllable words to form a new word on the board.; Lead learners to say the words.; Assist learners to read two syllable words.', 320),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B3.2.4.2', 'Recognise and read words with identical sounds', 'B3.2.4.2.4', 'Read three-syllable words and segment them into syllables', 'Let learners say the letters of the alphabet.; Form one-syllable words and lead learners to say the words.; Join two of the one-syllable words to form a new word on the board.; Lead learners to say the words.; Write three-syllable words on flashcards.; Show it to the learners to read the words and segment them into syllables.', 330),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and Sound Knowledge', 'B3.2.4.2', 'Recognise and read words with identical sounds', 'B3.2.4.2.5', 'Read one-syllable words with consonant clusters', 'Let learners say the letters of the alphabet.; Form one-syllable words and lead learners to say the words.; Join two of the one-syllable words to form a new word on the board.; Read several one-syllable words with consonant clusters to learners.; Allow learners to read one syllable words with consonant clusters.', 340),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and Content Vocabulary)', 'B3.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B3.2.5.1.1', 'Read texts aloud with correct pronunciation and tone', 'Let learners say the letters of the alphabet as a group and then individually.; With correct pronunciation and tone read texts aloud.; Let learners read texts aloud with correct pronunciation and tone as a group and then individually.', 350),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and Content Vocabulary)', 'B3.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B3.2.5.1.2', 'Play a variety of words and sentence games', 'Revise the lesson on traditional games with learners.; Put learners into groups.; Let them play a word and sentence game.; Allow learners to play with a variety of words and sentence games.; Let learners talk about their experiences group by group.', 360),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B3.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B3.2.6.1.1', 'Answer questions based on passage read to them', 'Let learners say the letters of the alphabet as a group and then individually.; With correct pronunciation and tone read texts aloud.; Let learners read the text in turns.; Ask questions based on the text read for learners to answer.', 370),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B3.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B3.2.6.1.2', 'Answer questions based on passage read by learners', 'Let learners say the letters of the alphabet as a group and then individually.; Give textbooks to learners.; Lead learners to read the text on a given page as a group and individually.; Ask questions based on the text they have read for them to answer.', 380),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Silent Reading', 'B3.2.7.1', 'Demonstrate knowledge on reading for comprehension', 'B3.2.7.1.1', 'Read longer sentences', 'Let learners say the letters of the alphabet as a group and then individually.; Write long sentences on a card.; Show the card with the sentences to learners.; Read aloud the long sentences.; Let learners read longer sentences as a group and the individually', 390),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Silent Reading', 'B3.2.7.1', 'Demonstrate knowledge on reading for comprehension', 'B3.2.7.1.2', 'Read short passages/text', 'Let learners say the letters of the alphabet as a group and then individually.; Write a short passage on a card.; Show the card to learners.; Read aloud the long passage.; Let learners read the short passage as a group and the individually.; Ask learners questions based on the short passage read for them to answer.', 400),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Fluency', 'B3.2.8.1', 'Exhibit knowledge by reading aloud with minimal mistakes', 'B3.2.8.1.1', 'Read short passages of about six to ten sentences aloud using correct tone', 'Let learners say the letters of the alphabet as a group and then individually.; Write a short passage of about six to ten sentences.; Read aloud the short passage of about six to ten sentences using correct tone for learners to listen.; Lead learners to read the passage.; Let learners read aloud the passage as a group and then individually.; Ask questions based on the passage read for learners to answer.', 410),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B3.3.1.1', 'Write and practise saying letters or words with which learners have difficulty; copy various sentences, verses and words of songs legibly', 'B3.3.1.1.1', 'Write letters and words', 'Let learners say the letters of the alphabet as a group and individually.; Write letter and words boldly on the board.; Give learners some letters and words to write on their own.; Assist learners to write letters and words given them.', 420),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B3.3.1.1', 'Write and practise saying letters or words with which learners have difficulty; copy various sentences, verses and words of songs legibly', 'B3.3.1.1.2', 'Copy simple sentences boldly and clearly', 'Let learners say the letters of the alphabet as a group and individually.; Write simple sentences boldly on the board.; Lead learners to read the sentences aloud as a group.; Let learners read the sentences aloud in turns.; Let learners copy the simple sentences boldly and clearly in their books.', 430),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Simple Words/Names of People and Places (Proper Nouns) Labelling Items in the Environment/Classroom', 'B3.3.3.1', 'Write simple words/names of people and places (proper nouns)', 'B3.3.3.1.1', 'Write simple words/names of people and places', 'Let learners mention names of places and names of their friends.; Create people and place names map on a cardboard.; Show the map to learners and discuss it with them.; Assist learners to write simple words or names of people and places in their books.', 440),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Writing Simple Words/Names of People and Places (Proper Nouns) Labelling Items in the Environment/Classroom', 'B3.3.3.2', 'Show understanding of items in the environment/ classroom', 'B3.3.3.2.1', 'Say and label items in the classroom and in the environment', 'Ask learners to sing a popular song they know.; Display some items in the environment in the classroom.; Call a learner to lead the class to discuss, recognise and name the items.; Draw the items on the board and write their names on a card.; Call learners to pick a card and fix it under the item the name written on the card refers to.; Mention some items seen in the classroom and ask learners to point at the items mentioned.; Let learners mention and label more items in the classroom and in the environment.', 450),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Copying/Writing Simple Sentences with Correct Spacing', 'B3.3.4.1', 'Exhibit knowledge of writing simple sentences with correct word spacing', 'B3.3.4.1.1', 'Write correct sentences with correct spacing from substitution table', 'Let learners explore a rhyme they know.; Make a substitution table on the board.; Lead learners to say aloud the words in the substitution table.; Let learners say aloud the words in the substitution table individually.; Demonstrate how sentences are formed from a substitution table.; Help learners to write correct sentences with correct spacing from the substitution table.', 460),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Copying/Writing Simple Sentences with Correct Spacing', 'B3.3.4.1', 'Exhibit knowledge of writing simple sentences with correct word spacing', 'B3.3.4.1.2', 'Use upper case or lower-case letters correctly in sentences with correct spacing', 'Let learners explore a rhyme they know or say the letters of the alphabet as a group.; Create upper and lower-case letters game.; Play the game with learners.; Let one learner lead the other learners to play the game (supervision is necessary).; Write sentences on the board using upper and lower-case letters.; Help learners to use upper case or lower-case letters correctly in writing sentences with correct spacing.', 470),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B3.5.1.1', 'Exhibit knowledge of using capital letters appropriately', 'B3.5.1.1.1', 'Understand the use of capital letters to write proper nouns', 'Let learners sing any play song they know.; Create a game that helps to use capital letters to write proper nouns.; Through the game help learners to understand the use of capital letters to write proper nouns.', 480),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B3.5.1.1', 'Exhibit knowledge of using capital letters appropriately', 'B3.5.1.1.2', 'Comprehend the use of capital letters to write sentences', 'Let learners sing any play song they know.; Create a game that helps learners to use capital letters to write sentences.; Help learners to understand the use of capital letters to write correct sentences.', 490),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B3.5.1.1', 'Exhibit knowledge of using capital letters appropriately', 'B3.5.1.1.3', 'Understand and use capital letters after sentences and full stops', 'Let a learner lead the class to sing a popular song they know.; Tell learners why we use capital letters after sentences and full stops.; Help learners to understand the use of capital letters after sentences and full stops using illustrations on the board.', 500),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Punctuation)', 'B3.5.2.1', 'Show an understanding of using punctuation marks appropriately', 'B3.5.2.1.1', 'Understand and use full stops and commas', 'Let a learner lead the class to sing a popular song they know.; Create a game on the Show an understanding of the use of full stops and commas.; Play the game with learners.; Help learners to understand the use of full stops and commas.', 510),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Punctuation)', 'B3.5.2.1', 'Show an understanding of using punctuation marks appropriately', 'B3.5.2.1.2', 'Understand the use of full stops at the end of sentences', 'Let the class sing a popular traditional occupational song they know.; Create a game on the use of full stops.; Play the game with learners and let learners play the game in groups.; Help learners to show an understanding of the use of full stops at the end of sentences.', 520),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Punctuation)', 'B3.5.2.1', 'Show an understanding of using punctuation marks appropriately', 'B3.5.2.1.3', 'Recognise and use punctuation marks in sentences', 'Let the class sing a popular traditional occupational song they know.; Create a game on the use of punctuation marks.; Play the game with learners and let learners play the game in groups.; Help learners to recognise and use punctuation marks in sentences.', 530),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Action Words)', 'B3.5.3.1', 'Demonstrate knowledge on recognition of action words', 'B3.5.3.1.1', 'Recognise present continuous action words in sentences', 'Write sentences in continuous action on cardboards.; Discuss it with learners.; Help learners to recognise present continuous action words in sentences. E.g. going, coming, eating and drinking.', 540),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Action Words)', 'B3.5.3.1', 'Demonstrate knowledge on recognition of action words', 'B3.5.3.1.2', 'Write present continuous action words correctly', 'Write present continuous action words on flashcards.; Lead learners to say the words as a group and then individually.; Use the flashcards to help learners to write present continuous action words in sentences.; Give learners some action words and let learners write the present continuous forms. E.g. Sitting, walking, jumping and thinking.', 550),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Action Words)', 'B3.5.3.1', 'Demonstrate knowledge on recognition of action words', 'B3.5.3.1.3', 'Use present continuous action words in simple sentences', 'Let learners sing a popular play song they know.; Through games help learners to use present continuous action words in sentences. E.g. I am sitting on a chair. I am walking home. Kojo is j umping.', 560),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Qualifying Words)', 'B3.5.4.1', 'Demonstrate knowledge on recognition of qualifying words (adjectives and adverbs)', 'B3.5.4.1.1', 'Know and use comparative words/adjectives in sentences', 'Let learners say the names of the days of the week.; Use simple adjectives to form simple sentences and lead learners to read.; Underline the adjectives and discuss the adjectives with learners.; Help learners to understand and use adjectives to form simple sentences. E.g. Kofi is taller than Yaw. Ama is smaller than Adwoa.', 570),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Qualifying Words)', 'B3.5.4.1', 'Demonstrate knowledge on recognition of qualifying words (adjectives and adverbs)', 'B3.5.4.1.2', 'Demonstrate knowledge of the use of adverbs', 'Revise the lesson on command and response with learners.; Write some action words on a card and lead learners to say the words aloud.; Discuss the action words with learners.; Use the action words to form sentences (the sentences should have adverbs in them). Through that help learners to understand adverbs and how they are used.', 580),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Qualifying Words)', 'B3.5.4.1', 'Demonstrate knowledge on recognition of qualifying words (adjectives and adverbs)', 'B3.5.4.1.3', 'Recognise adverbs from a group of words', 'Let learners mention some action words they know.; Write simple sentences with adverbs on the board/ card.; Lead learners to read the sentences.; Help learners to recognise adverbs from a group of words.; Put learners in groups to write about four adverbs and form sentences with them.', 590),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Postpositions)', 'B3.5.5.1', 'Exhibit knowledge of understanding recognising and using postpositions', 'B3.5.5.1.1', 'Recognise postpositions in sentences', 'Let learners mention names of objects in the classroom and the environment.; Use postposition to form simple sentences on a card.; Lead learners to read the sentences aloud.; Let learners read the sentences in turns.; Encourage learners to recognise postpositions in sentences.; Let learners write the postpositions in their books.', 600),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Postpositions)', 'B3.5.5.1', 'Exhibit knowledge of understanding recognising and using postpositions', 'B3.5.5.1.2', 'Explore the use of postpositions such as above and below in sentences', 'Let learners mention names of objects in the classroom and the environment.; Use postposition in simple sentences.; Lead learners to explore the use of postpositions such as above and below in sentences.; Put learners into groups and let them form a given number of sentences using the postpositions “above” and “below.”; Let learners read aloud their sentences to the class and discuss the sentences with learners.', 610),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Simple and Compound Sentences)', 'B3.5.6.1', 'Exhibit knowledge of recognising features of compound sentence in writing', 'B3.5.6.1.1', 'Recognise conjunctions in compound sentences', 'Let learners mention names of objects in the classroom and the environment.; Use conjunctions to form simple sentences on the board.; Call learners to read aloud the sentences.; Lead learners to discuss and recognise conjunctions in the sentences.; Let learners form their own sentences using a chosen conjunction.', 620),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Simple and Compound Sentences)', 'B3.5.6.1', 'Exhibit knowledge of recognising features of compound sentence in writing', 'B3.5.6.1.2', 'Use conjunctions to form compound sentences from simple sentences', 'Let learners mention names of objects in the classroom and the environment.; Write compound sentences on the board and lead learners to read the sentences.; Lead learners to underline the conjunctions in the sentences.; Help learners to use conjunctions to form compound sentences from simple sentences.; Put learners into groups and let them form a given number of sentences using conjunctions.; Let learners read aloud their sentences to the class and discuss the sentences with learners.', 630),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Use of Simple and Compound Sentences)', 'B3.5.6.1', 'Exhibit knowledge of recognising features of compound sentence in writing', 'B3.5.6.1.3', 'Use conjunctions such as but and because in forming compound sentences', 'Let learners mention names of objects in the classroom and the environment.; Write compound sentences on the board and lead learners to read the sentences.; Help learners to use conjunctions such as, “but” and “because” to form compound sentences.; Put learners into groups and let them form a given number of sentences using conjunctions “but” and “because.”; Let learners read aloud their sentences to the class and discuss the sentences with learners.', 640),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Spelling)', 'B3.5.7.1', 'Exhibit knowledge of recognising and spelling words correctly', 'B3.5.7.1.1', 'Write four and five letter words correctly', 'Let learners say the letters of the alphabet.; Write four and five letter words on flashcards.; Show the cards to learners and lead them to mention the words.; Use the flashcards to encourage learners to write four and five letter words correctly in their books.', 650),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Spelling)', 'B3.5.7.1', 'Exhibit knowledge of recognising and spelling words correctly', 'B3.5.7.1.2', 'Write five and six letter words correctly', 'Let learners say the letters of the alphabet.; Write five and six letter words on flashcards.; Show the cards to the learners and lead them to mention the words.; Use the flashcards to encourage learners to write five and six letter words correctly in their books.', 660),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/Usage', 'Integrating Grammar in Written Language (Spelling)', 'B3.5.7.1', 'Exhibit knowledge of recognising and spelling words correctly', 'B3.5.7.1.3', 'Write more than five and six letter words correctly', 'Let learners say the letters of the alphabet.; Write five and six letter words on flashcards.; Show the cards to learners and lead them to mention the words.; Encourage learners write more five and six-letter words correctly in their books.; Let learners say the words to the class.', 670),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children’s Literature/ Library', 'Building the Love and Culture of Reading', 'B3.6.1.1', 'Demonstrate knowledge by reading short stories with correct intonation', 'B3.6.1.1.1', 'Read short stories aloud correctly', 'Let learners explore a popular rhyme they know.; Read a short story aloud and correctly to learners.; Discuss the short story with learners.; Call them out one by one to read short stories aloud correctly.; Ask them questions based on the story read.', 680),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children’s Literature/ Library', 'Read Aloud with Children', 'B3.6.2.1', 'Demonstrate knowledge by reading short stories with correct intonation', 'B3.6.2.1.1', 'Read short stories aloud correctly', 'Sing a popular song with learners.; Read a short story aloud and correctly to learners.; Discuss the story with learners and read the story again.; Call them out one by one to read short stories aloud correctly.; Call learners to read a sentence each from the story.', 690),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children’s Literature/ Library', 'Reading Short Texts/Poems/Narratives/Short Stories and Respond to Them', 'B3.6.3.1', 'Exhibit knowledge of reading passages with understanding', 'B3.6.3.1.1', 'Read stories with correct intonation', 'Sing a popular song with learners.; Read a story with correct intonation to the class.; Lead learners to learn how to read stories with correct intonation.; Call learners out one after the other to read the story.; Ask questions based on the story read for learners to answer.', 700),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children’s Literature/ Library', 'Reading Short Texts/Poems/Narratives/Short Stories and Respond to Them', 'B3.6.3.1', 'Exhibit knowledge of reading passages with understanding', 'B3.6.3.1.2', 'Say the title and author of the book read', 'Discuss with learners where to locate the title and author of a book.; Let learners bring out any reading book from the cupboard and lead them to mention the titles and authors of the books they have.', 710),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children’s Literature/ Library', 'Reading Short Texts/Poems/Narratives/Short Stories and Respond to Them', 'B3.6.3.1', 'Exhibit knowledge of reading passages with understanding', 'B3.6.3.1.3', 'Discuss and explain the meaning of some words and pictures in the passage', 'Let learners scan through the reading book and write down the words that are unfamiliar to them.; Put learners into groups to compare the words that they have written and come out with one list.; Let each group write their words on the board and lead them to pronounce the words as a group and individually.; Discuss the meaning of some of the words with learners and encourage them to find the meaning of the other words.', 720),
('Basic 3', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children’s Literature/ Library', 'Reading Short Texts/Poems/Narratives/Short Stories and Respond to Them', 'B3.6.3.1', 'Exhibit knowledge of reading passages with understanding', 'B3.6.3.1.4', 'Answer questions based on a passage read', 'Lead learners to read a passage from the class reader and let learners read the passage as a group and then individually.; Ask questions for learners to answer.', 730),
('Basic 3', 'History', 'history', 'My Country Ghana', 'The People of Ghana', 'B3.2.1.1', 'Exhibit knowledge of the unique history of the major ethnic groups in Ghana', 'B3.2.1.1.1', 'Discuss the origins of the major ethnic groups in Ghana Enquiry route: What are the major ethnic groups in Ghana? Where did the major ethnic groups originate? Why did they move to their present locations?', '1. Identify some of the major ethnic groups. Eg. Guan, Mole-Dagbani/ Gonja, Akan, Ga/Adangme, Ewe; 2. Use a map to trace the routes the major ethnic groups travelled to get to their present-day locations in Ghana.; 3. In groups, learners discuss the origin of the major ethnic groups; 4. Compose a song with names of the major ethnic groups and where they originated (In the special schools, resource persons should assist the hearing impaired to sing); 5. Draw a map to locate the migratory routes of the ethnic groups. (this can also be done on a manila card); 6. Develop a timeline of the periods each ethnic group arrived in Ghana', 10),
('Basic 3', 'History', 'history', 'My Country Ghana', 'Inter-Group Relations', 'B3.2.2.1', 'Demonstrate knowledge of how intergroup alliances, conflicts and other exchanges', 'B3.2.2.1.1', 'Discuss the nature of exchanges among the ethnic groups. Enquiry route: What form did the exchanges take? How beneficial were these exchanges to the ethnic groups?', '1. Identify the forms of exchanges including forms of trade, inter-marriage, conflict and alliances.; 2. Discuss the benefit of these exchanges', 20),
('Basic 3', 'History', 'history', 'My Country Ghana', 'Inter-Group Relations', 'B3.2.2.1', 'Demonstrate knowledge of how intergroup alliances, conflicts and other exchanges', 'B3.2.2.1.2', 'Name some of the items exchanged among the various groups. Enquiry route: What items were exchanged among the various ethnic groups? Why were these items exchanged? How and why did cowrie shells (cedie) become the most common medium of exchange? Discuss the transformation from barter system to the use if cowry shells as a medium of exchange', '1. Identify trade items that were exchanged among ethnic groups: salt. fish, gold, kola, Shea butter, pottery and cloth and iron utensils; 2. Match items with the areas / sources where the items were obtained. e.g. Shea butter - savannah belt; 3. Explain the medium of exchange; 4. Trace the origin of the name ‘cedi’', 30),
('Basic 3', 'History', 'history', 'My Country Ghana', 'Inter-Group Relations', 'B3.2.2.1', 'Demonstrate knowledge of how intergroup alliances, conflicts and other exchanges', 'B3.2.2.1.3', 'Describe the conflicts and alliances that existed among the ethnic groups in Ghana Enquiry route: Which ethnic groups were engaged in wars in the past? Which ethnic groups came together to fight a war?', '1. Discuss intergroup wars such as Battle of Feyiase and the Krepi war of 1833. Discuss instances where alliances were formed between different groups to fight a common enemy. E.g. The Battle of Akatamanso where the Asante army was defeated by an alliance made up of the British, Ga, Fante, Akyem, Akwamu, Krepi and Denkyira Anlo / Asante in the Ada War of 1869', 40),
('Basic 3', 'History', 'history', 'My Country Ghana', 'Major Historical Locations', 'B3.2.4.1', 'Demonstrate knowledge of the forts and castle built in Ghana', 'B3.2.4.1.1', 'Identify the forts and castles built along the coast of Ghana Enquiry Route: what is the difference between a fort and castle? Where can we locate the forts and castles? Who built them? When were they built? Why were they built? How have the uses of forts and castles changed over time?', '1. Explain the differences between forts and castles; 2. With the use of internet, identify the major forts and castles on Ghana’s coast on a map (where they are located, which Europeans built them and when and why they were built).; 3. Explain some of the uses to which these forts and castles have been put since they were built. E.g. Seat of government, trading and education; 4. Discuss the use to which these forts and castles were put since Ghana gained independence; 5. Match these forts and castles with where they can be located; 6. Learners draw their favourite castle; 7. Show and discuss a documentary/ slides on forts and castles in Ghana ** Visit any of these facilities to model any fort and castle', 50),
('Basic 3', 'History', 'history', 'My Country Ghana', 'Some Selected Individuals', 'B3.2.5.1', 'Describe the contributions of some outstanding Ghanaian entrepreneurs', 'B3.2.5.1.1', 'Describe Ghanaian entrepreneurs who have made significant contributions including George Grant', '– Businessman, Winifred Tete-Ansa, Esther Ocloo – Nkulenu Industries, B.A. Mensah – Pioneer Tobacco Ltd. Kwabena Pepra – Paramount Distilleries, J.K. Siaw – Tata Brewery, Alhaji Adam Iddrisu - Global Haulage Enquiry route: Which Ghanaian entrepreneurs contributed to national development? How did they contribute? Which entrepreneurs inspires you most and why? 1.Name Ghanaian entrepreneurs of note e.g. George Grant – Businessman, Winifred Tete-Ansa, Esther Ocloo – Nkulenu Industries, B.A. Mensah – Pioneer Tobacco Ltd. Kwabena Pepra – Paramount Distilleries, J.K. Siaw – Tata Brewery, Alhaji Adam Iddrisu – Global Haulage 2.Show pictures of some outstanding entrepreneurs in Ghana 3.Retell the live stories of any of these entrepreneurs from a documentary show; 4. Identify the entrepreneurs who work inspires you most and give reasons for your choice', 60),
('Basic 3', 'History', 'history', 'Europeans in Ghana', 'Arrival of Europeans', 'B3.3.1.1', 'Show understanding of the interactions between the local people and early settlers', 'B3.3.1.1.1', 'Describe how the Europeans settled on the Gold Coast, including forming alliances with the local chiefs Enquiry route: Which Europeans were the first to come to the Gold Coast? When did they come? Where did they first settled?', '1. Dramatise the meeting between the Portuguese and Kwamina Ansah; 2. Explain why other Europeans who came later also settled on the Gold Coast; 3. Investigate how the Europeans settled on the Gold Coast including forming alliances with the local chiefs and marrying the local people', 70),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B3.1.1.1', '` Count and estimate quantities from 0 to 10,000', 'B3.1.1.1.1', 'Use number names and the counting sequence to count and estimate quantities up to 10,000', 'E.g.; 1. Skip count forwards and backwards from 0 to 10,000 by 10s, 50s 100s, 500s and 1000s starting at any point. Identify and correct errors or omissions in a skip counting sequence E.g.; 2. Count to tell the number of objects in given collection of objects by selecting the most appropriate of three estimates for a given collection of objects and justify the choice. E.g. 3 Represent numbers or quantities to 1000 with written numerals E.g. 4 Write number words for given multiples of ten to 9999 and for multiples of 100 to 99990', 10),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B3.1.1.1', '` Count and estimate quantities from 0 to 10,000', 'B3.1.1.1.2', 'Identify numbers in different positions around a given number in a number chart', 'E.g.; 1. Display a number chart with numbers between 0 and 10,000 and have learners identify numbers in different positions around a given number. Put learners in convenient groups and give each group a number grid and have them identify numbers in different positions around a chosen number. For example, choose 34 and identify numbers above, below, to the right or to the left etc. 1204 848 1175 112 253 2418 3806 1640 4615 4909 634 2990 6320 3832 7479 4768 910 8091 9802 9007', 20),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B3.1.1.1', '` Count and estimate quantities from 0 to 10,000', 'B3.1.1.1.3', 'Describe numbers and the relationship between numbers from 0 to 10,000 in equivalent ways using the place value concept', 'E.g.; 1. Demonstrate a conceptual understanding of place value of whole numbers between 100 and 10,000 by: - explaining and showing - with bundles of hundreds, tens and ones - the meaning of each digit in a given 3-digit number (when the three digits are different, as well as when two or more of the digits are the same) and representing the number in a hundreds frame - explaining why the value of a digit depends upon its placement within a numeral.', 30),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B3.1.1.1', '` Count and estimate quantities from 0 to 10,000', 'B3.1.1.1.4', 'Compare and order whole numbers up to 10,000 and represent comparisons using the symbols >, <, or =', 'E.g.; 1. Demonstrate an understanding of how place value determines the relative size of whole numbers (between 100 and 10,000) by: - describing the relative size of two numbers (i.e., saying whether one number is a little or a lot bigger or smaller than another and justifying the answer) - identifying which of two given numbers is bigger (or smaller), explaining why using place value and representing the relationship using the symbols< and >; - putting a small group of numbers in increasing or decreasing order and justifying the order using a hundreds frame, a number line or place value; - identifying the missing numbers or errors in a section of number line from 100 to 10,000 or in a hundreds chart and justifying the answer using place value - solving word problems that involve comparing quantities to 1000 (i.e., Agbo has 230 chickens. Dzifa has 460. What can you say?)', 40),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B3.1.1.2', 'Develop an understanding of positive and negative numbers', 'B3.1.1.2.1', 'Describe situations having opposite directions or values', 'E.g.; 1. Invite pairs of learners to play the "opposite game" (i.e. a learner performs an action and the partner does the opposite whilst the rest of the class serve as referees) E.g.; 2. Make a space down the centre of the classroom and mark with chalk cross and ask a pair to stand on the cross with their back facing. the learners then move in the opposite direction a straight line', 50),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B3.1.1.2', 'Develop an understanding of positive and negative numbers', 'B3.1.1.2.2', 'Use real life contexts to deduce positive and negative number representations', 'E.g.; 3. Draw a large picture showing the sea, mountains above the sea and space below sea level. Provide pictures of items such as a fish, a whale, a boat, car, house, an octopus etc. Ask the learners where they would place each of the items on your picture. Encourage them to say "above the sea level" or "below the sea level". When all the items are stuck, discuss how high the plane might be and how low the octopus might be and so on. Introduce the "minus" sign to indicate under the sea level', 60),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Counting, Representation, Cardinality & Ordinality', 'B3.1.1.3', 'Identify negative numbers up to -10', 'B3.1.1.3.1', 'Describe situations using positive and negative values', 'E.g.; 1. Draw a number line on the floor or any convenient place. Ask a pair to stand on the cross (centre) with their back facing. The learners then move in the opposite direction a straight line on the number line. Have learners move on the opposite direction on the number line and name the numbers as shown: Learners also build their own number line to include -10 A blank number line', 70),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.1', 'Develop and use standard strategies for adding and subtracting within 1000', 'B3.1.2.1.1', 'Use standard strategy or procedure to do addition or subtraction within 1000', 'E.g.; 1. Explain the purpose of a symbol like a square or an underline in a given addition or subtraction mathematics sentences with one unknown (e.g.: 227 + ☐ = 609) E.g.; 2. Create an addition or subtraction question with an unknown for a classmate to solve, and using either ☐ or ___ to represent the unknown E.g.; 3. Solve an addition or subtraction question with one unknown, using a variety of strategies and explaining the strategy used. E.g.; 4. Use the methods of decomposition to find the sums and difference of numbers within 1000', 80),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.2', 'Demonstrate an understanding of the concept of “equality” and “not equal to” in addition and subtraction problems with sums up to 1000', 'B3.1.2.2.1', 'Use the concept of "equal to" and "not equal to"', 'E.g.; 1. Explain that “≠” means “not the same as” or “not equal to” learners construct two sets that are not equal, explaining why they are not equal and recording the relationship using the symbol ≠ (e.g., ≠ ); - Change two given sets, equal in size, to create sets that are not equal (e.g., change = to ≠ ), explain the changes made and why - learners determine whether two sides of a given number sentence are equal or not and using the appropriate symbol to represent the relationship (e.g., 160 ≠ 80 + 50); E.g. 3. Learners demonstrate an understanding of the relationship between addition and subtraction by describing a subtraction as an equivalent addition and vice versa; i.e. finding the missing addend. (For example, that subtract 40 – 28 is the same as finding the number that must be added to 28 to make 40). 40 − 28 = What? Means 28 + What? = 40 Or if given 40 - 28 = ___ change question to 28 +__ = 40. The answer is 12, so 40 - 28 = 12).', 90),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.3', 'Develop and use strategies for mentally computing basic addition and subtraction facts within 100', 'B3.1.2.3.1', 'Use strategies to mentally add and subtract whole numbers within 100', 'E.g. 1 Use strategies studied in B1 and B2 (counting up, counting down, making doubles, making doubles plus or minus 1 or 2, making 10s, rearranging order of additions to make friendlier combinations, converting a subtraction into an addition and solving the addition) to demonstrate mastery of basic addition facts to 18 (and related subtraction facts) E.g.2 Make doubles when both numbers are close to doubles or when one number is close to the double of the other by: - decomposing one of the numbers to create doubles (e.g. when adding 25 + 26, think 25 + 25 +; 1) or - shifting a quantity from one number to the other to create doubles (e.g., when adding 24 + 26, think 25 + 25, or when adding 69 + 23, think 70 +; 22) E.g. 3 Make 10s when one number is close to 10 or to multiples of 10 by shifting a quantity from one number to the other to create a multiple of 10 (e.g. for example, instead of 28 + 47, think 30 + 45, which is the equivalent of moving 2 from 47 to 28 or think 25 + 50, which is the equivalent of moving 3 from 28 to 45); E.g. 3 Making 10s when the 2nd number is to 10 or to a multiple of 10 by compensation (i.e., adding something to the number, then adjusting the answer by adding the same amount to the answer e.g. for 48 – 19, subtract: 48 - 20 which is 18, then add 1 to that answer to get 19). E.g. 4 Subtracting by counting up in friendly jumps. Start at 2nd number and jump up by friendly jumps to get to the first number and add up all the friendly jumps made (e.g.,71-36, start with 36 and make friendly jumps until you get to 71, for example 36 + 10 + 10 + 10 + 5 gives 71. The jumps made were 10 + 10 + 10 + 5, or 35 places in total. So the difference between 71 and 36 is 35)', 100),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.4', 'Develop and apply personal and standard strategies for adding and subtracting within 1000', 'B3.1.2.4.1', 'Use a variety of personal strategies for adding within 1000', 'E.g. 1 Use objects (groups of 100s, 10s and ones) or drawings to model addition and subtraction of 1 to 3 digit numbers (with answers to 1000) and record Addition frame the process Hundreds Tens Ones symbolically, with and without a 100s frame. +', 110),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.4', 'Develop and apply personal and standard strategies for adding and subtracting within 1000', 'B3.1.2.4.2', 'Use a variety of personal and standard strategies to solve different types of subtraction and addition equations and problems with missing numbers in all positions', 'E.g.; 1. Splitting or partial sums, or adding 100s together first, then 10s together, then 1s, and then adding those partial sums together (see example of 168 + 384 to right); Tens', 120),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.4', 'Develop and apply personal and standard strategies for adding and subtracting within 1000', 'B3.1.2.4.3', 'Develop and explain estimation strategies to estimate the solution for a given word problem involving addition or subtraction sums up to 1000', 'E.g.; 1. To estimate the sum of 430 + 561, use 400 + 500. The sum must be close to 900; to estimate the different of 660 and 430, use 600 and 400 or 700 and 400. The difference must be close to 200 or 300.)', 130),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.4', 'Develop and apply personal and standard strategies for adding and subtracting within 1000', 'B3.1.2.4.4', 'Show an understanding of the property of commutativity', 'E.g.; 1. Give addition problems and have learners interchange the position of the addends and solve. for example 236 + 453 = and 453 + 236 =', 140),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.5', 'Demonstrate an understanding of multiplication up to 5 x 5', 'B3.1.2.5.1', 'Represent and explain multiplication using equal groupings Learners make formation of sets of equal object from a given quantity', 'For example with 12 straws Learners make groupings such as: 3 𝑔𝑟𝑜𝑢𝑝𝑠 𝑜𝑓 4 ⇒ 3 ×4 4 𝑔𝑟𝑜𝑢𝑝𝑠 𝑜𝑓 3 ⇒ 4×3 2 𝑔𝑟𝑜𝑢𝑝𝑠 𝑜𝑓 6 ⇒ 2×6', 150),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.5', 'Demonstrate an understanding of multiplication up to 5 x 5', 'B3.1.2.5.2', 'Represent and explain multiplication using rectangular arrays', 'E.g.; 1. To find 2×3= ? Learners arrange 2 straws vertically (legs) and put across it with 3 horizontal ones (arms). Learners count the number of intersections. E.g.; 2. Learners model different multiplication sentences. Learners mention the number of dots (intersections) for other learners to model fence. Note: Alternatively, learners may draw vertical lines to represent the legs and horizontal lines across them to represent the arms and then count the number of intersections as the product. E.g.; 3. Develop and build the multiplication chart (up to 9 x; 9) and have learners practice reading the chart', 160),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.6', 'Demonstrate an understanding of division', 'B3.1.2.6.1', 'Use concrete and pictorial representations to explain division as equal sharing or partitioning equally into given groups and finding how many are in each group', 'E.g.; 1. Give a quantity of straws (e.g.; 12) and invite 4 learners to share equally among themselves by picking one at a time in turns until all straws are finished and then asking each learner to count and tell the number of straws they received.', 170),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.6', 'Demonstrate an understanding of division', 'B3.1.2.6.2', 'Use concrete and pictorial representations to explain division as repeated subtraction or determining the number of times given equal groups can be obtained in (i.e. goes into or can be subtracted from) a given number', 'E.g. 1 Give a quantity of straws (e.g.; 12) and have learners make equal groups formation of 3 straws in each group and then have learners count the number of equal groups formed.', 180),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Number Operations (Addition, Subtraction, Multiplication and Division)', 'B3.1.2.6', 'Demonstrate an understanding of division', 'B3.1.2.6.3', 'Use concrete and pictorial representation to explain division as inverse of multiplication', 'E.g. 1 Explain that division can be carried out as an inverse of multiplication by the following process: For example, to solve 12 ÷3. Write: 12 ÷3= What? Which means What? = 12 3 × Learners use the multiplication chart to identify the number which multiplies 3 to obtain 12 Learners choose the number as the answer to the problem That is 12 ÷3= 4', 190),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Fractions', 'B3.1.3.1', 'Develop an understanding of fractions using concrete and pictorial representations and write fractions in words and symbols', 'B3.1.3.1.1', 'Understand a unit fraction by explaining the fraction as the quantity 𝒇 obtained by taking 1 part when a whole is partitioned into f equal parts and that a 𝟏 𝟏 fraction is the quantity obtained by taking parts of the size 𝒇 𝒇', 'E.g.; 1. Use several pictorial representations (or card cut outs) to introduce unit fractions like half, thirds, fifths, tenths, etc. and ask learners to identify the fractions A, B, C, D, and E E.g.2. Introduce the fraction notation by explaining the fraction one-half as the quantity obtained 1 by taking 1 part when a whole is partitioned into 2 equal parts and is represented by ; 2 ask learners to write symbols for the fractions A, B, C, D, and E E.g.; 3. Ask learners to match pictorial representations of fractions to their symbols', 200),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Fractions', 'B3.1.3.1', 'Develop an understanding of fractions using concrete and pictorial representations and write fractions in words and symbols', 'B3.1.3.1.2', 'Understand, explain and demonstrate that fractions can be used to represent parts of a group of objects, point on a line, or distances on a number line [Read and write fractions using words and symbols. (', 'E.g. one-half, two halves, thirds, fifths etc.)] E.g.; 1. Use concrete objects and pictorial representations to explain the fraction half as the quantity obtained by taking 1 part when a group of object is partitioned into two equal parts. E.g.; 2. Ask learners to colour given fractions of given groups of object or match fractions to given groups of objects', 210),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Fractions', 'B3.1.3.1', 'Develop an understanding of fractions using concrete and pictorial representations and write fractions in words and symbols', 'B3.1.3.1.3', 'Compare and order unit fractions and fractions with like denominators by using concrete models, pictorial representations and number line. 3 1', 'E.g.; 1. Use pictorial representations to compare pairs of fractions. Which is larger, and ? 8 4 3 2 5 Arrange from smallest to largest , and 6 3 6 3 1 E.g.; 2. Use fraction charts to compare pairs of fractions. Which is larger, and ? Arrange 8 4 3 2 5 from smallest to largest , and 6 3 6', 220),
('Basic 3', 'Mathematics', 'maths', 'Number', 'Fractions', 'B3.1.4.1', 'Determine the value of coins and notes in order to solve monetary transactions', 'B3.1.4.1.1', 'Use different denominations of money (1,2, 5, 10, 20, 50 cedis notes an pesewas coins) to buy and give change', 'E.g.; 1. Solve word problems involving money including 1,2, 5, 10 and 20 cedi denominations and giving change Display a chart with items and their prices as in the example below Ask learners to copy and complete the table (based on items and their prices in the picture and find the change to receive in each case Shopping money Items to buy Change to receive; 1. GH¢100 3 shirts; 2. GH¢50 4 books; 3. GH¢5 8 pencils; 4. GH¢10 4 bottles coca cola', 230),
('Basic 3', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationship', 'B3.2.1.1', 'Recognise, create, extend, describe, and use patterns and rules to solve mathematical tasks', 'B3.2.1.1.1', 'Demonstrate an understanding of increasing and decreasing patterns by extending the next two or three terms and identifying errors or missing elements', 'E.g. 1 Identify the pattern rule used to create more complex increasing or decreasing pattern and extend the pattern for the next 2 or 3 terms e.g. - 3, 6, 9, 12, 15… - the rule is “add 3 or take 3 steps forward or - 30, 27, 24, 21, 18 … - the rule is take 3 steps backwards or subtract; 3) E.g. 2 Create a pattern for a given pattern rule (e.g., create a pattern for the rule “add 10”) E.g. 3 Identify errors or missing elements in an increasing or decreasing pattern and justify the answer e.g. - 5, 10, 20, 25, 30 … or - 45, 40, 35, 30, __, 20 … E.g. 4 Locate and describe increasing or decreasing patterns in a 100s chart (horizontal, vertical, diagonal patterns, etc.)', 240),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'D & 3D Shapes', 'B3.3.1.1', 'Analyse the relationships among and between 2-D shapes and 3-D objects according to a variety of attributes, including measurement', 'B3.3.1.1.1', 'Describe 3D objects according to the shape of the faces, the number of edges and vertices. Sort regular and irregular polygons including triangles, quadrilaterals, pentagons, heptagons according to the number of sides', 'E.g.; 1. Identify a variety of 3D shapes (cubes, spheres, cones, cylinders, pyramids and prisms) by: - identifying and counting the faces, edges and vertices: - describing the shape of the faces - constructing a skeleton of an object and describing the relationship between the skeleton and the object E.g.; 2. Sort a collection of 3D objects according to the number/nature of faces, number of edges or number of vertices and describe sorting rule used E.g.; 3. Identify regular and irregular 2D shapes (triangles, rhombus, rectangles, squares, pentagons, hexagons, octagons) having different dimensions and orientations by the number and nature of sides', 250),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'D & 3D Shapes', 'B3.3.1.1', 'Analyse the relationships among and between 2-D shapes and 3-D objects according to a variety of attributes, including measurement', 'B3.3.1.1.2', 'Draw and identify angles', 'E.g.; 1. Sort 2D shapes into larger categories (e.g. rhombuses, rectangles and squares are all four-sided shapes.) according to a common, shared attribute and justify sorting; Draw examples of shapes that belong to and those that do not belong to given category E.g.; 2. Measure the sides of a given polygon; Draw a polygon with given sides', 260),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'D & 3D Shapes', 'B3.3.1.1', 'Analyse the relationships among and between 2-D shapes and 3-D objects according to a variety of attributes, including measurement', 'B3.3.1.1.3', 'Use cut-out paper as a square corner to determine angles which are right angles and angles which are not right angles', 'E.g.; 1. Identify polygons with square corners and those without square corners in and around their environment using cut-out papers', 270),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'D & 3D Shapes', 'B3.3.1.1', 'Analyse the relationships among and between 2-D shapes and 3-D objects according to a variety of attributes, including measurement', 'B3.3.1.1.4', 'Use attributes to recognize rhombuses, parallelograms, trapezoids, rectangles, and squares as examples of quadrilaterals and draw examples of quadrilaterals that do not belong to any of these subcategories', 'E.g.; 1. Give cut-out shapes of different types of quadrilaterals and have learners examine their features. Learners discuss the characteristics and regroup them as rhombuses, parallelograms, trapezoids, rectangles, and squares and draw these quadrilaterals', 280),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'Position/ Transformation', 'B3.3.2.1', 'Demonstrate that the length of an object does not change with its placement or direction', 'B3.3.2.1.1', 'Represent whole numbers as distances from any given location on a number line', 'E.g.; 1. Learners draw the number line, place rod A on different number points and count the number of unit intervals it covers in order to determine its length. Do same to rods B, C and D.', 290),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Length, Mass, Time', 'B3.3.3.1', 'Demonstrate an understanding of a metre and centimetre (cm, m) units for measuring length', 'B3.3.3.1.1', 'Model and describe the relationship between the units metre and centimetre', 'E.g.; 1. Guide learners to study the calibration on the tape measure, metre rule and ruler E.g.; 2. Identify objects that measure approximately 1 cm or 1m; Estimating the length of given objects using these base objects as a reference point or point of comparison E.g.; 3. Identify the appropriate standard unit (cm or m) for measuring the length of a given object E.g.; 4. Estimate, then measure, using a ruler and recording the length and width of 2 D shapes or the length, width and height of given 3D objects E.g.; 5. Draw a line segment of a given length with a ruler, grid paper etc. E.g.; 6. Demonstrate the relationship between 100 cm and 1 m using concrete materials', 300),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Length, Mass, Time', 'B3.3.3.1', 'Demonstrate an understanding of a metre and centimetre (cm, m) units for measuring length', 'B3.3.3.1.2', 'Select and justify referents for metre and centimetre', 'E.g.; 1. Make or show a list of items in the learners environment and have learners select and justify the choice of referents for measuring the length of the item mentioned', 310),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Length, Mass, Time', 'B3.3.3.1', 'Demonstrate an understanding of a metre and centimetre (cm, m) units for measuring length', 'B3.3.3.1.3', 'Estimate lengths, heights and perimeter of regular and irregular shapes using referents and verify by measuring, using a ruler or tape', 'E.g.; 1. Measure and record the perimeter of a given regular or irregular shape and explain the strategy used E.g.; 2. Construct shapes for a given perimeter (cm or m); Construct more than one shape for the same given perimeter to demonstrate that many shapes are possible for a given perimeter E.g.; 3. Estimate the perimeter of a given shape (cm, m) using personal reference points for length, then measure to assess the accuracy of the estimation', 320),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Length, Mass, Time', 'B3.3.3.2', 'Demonstrate an understanding of kilogram and gram (Kg, g) unit for measuring mass and millitre and litre (ml, l) for measuring capacity', 'B3.3.3.2.1', 'Model and describe the relationship between the units Kilogram and gram as well as litres and millilitres', 'E.g.; 1. Identify objects that weigh approximately 1 g or 1 kilogram (or that hold 1 ml or 1 l). Estimating the mass, or capacity of given objects using these objects as a reference point or point of comparison E.g.; 2. Identify the appropriate standard unit (g or Kg; ml or l;) for measuring the mass or capacity of a given object E.g.; 3. Estimate, then measure, using a scale (or graduated cylinder) and recording the mass (capacity) of common, everyday objects to the nearest g or kg (or ml or l). E.g.; 4. Explain the relationship between 1000 g and 1 kg using a model or balance or between 1000 ml and 1 l using a graduated cylinder', 330),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Length, Mass, Time', 'B3.3.3.2', 'Demonstrate an understanding of kilogram and gram (Kg, g) unit for measuring mass and millitre and litre (ml, l) for measuring capacity', 'B3.3.3.2.2', 'Estimate masses and volumes using referents and verify by measuring, using a pan balance and weights, calibrated measuring cans', 'E.g.; 1. Bring to class a collection of different types of objects and have learners estimate their weights or volumes using direct or indirect comparisons and then later verify the estimate by using standard measuring tools', 340),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Length, Mass, Time', 'B3.3.3.3', 'Demonstrate an understanding of time taken by events in days, weeks and months', 'B3.3.3.3.1', 'Use arbitrary units to measure time taken to complete simple events', 'E.g.; 1. Identifying personal referents for minutes or hours (i.e., 10 minutes is about the time it takes to…or 3 hours is about the time it takes to…) E.g.; 2. Identifying activities that can or cannot be accomplished in minutes, hours, days, months and years E.g.; 3. Ask learners to time, using watches or clock and tell how much time (in minute and seconds) it would take to iv. walk round the school building; v. walk to the nearest house to the school; vi. walk to the nearest toilet; etc. E.g.; 4. Give learners the start and end times of events and ask to determine the duration of the event E.g.; 5. Complete the table Sporting event Start Finish How long? Ampe 10.30 a.m. 10.45 a.m. Netball 9.00 a.m. 10.00 a.m. Basket ball 2.00 p.m. 3.50 p.m. Football 3.30 p.m. 5.00 p.m.', 350),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Length, Mass, Time', 'B3.3.3.3', 'Demonstrate an understanding of time taken by events in days, weeks and months', 'B3.3.3.3.2', 'Read dates on the calendar, order dates of events and count days, weeks, months and years taken by given events', 'E.g.; 2. Ask learners to say the rhyme “Thirty-days has September” 30 days has September, April, June, and November. All the rest have 31, Except for February alone, which has 28 days clear, and 29 in each leap year. E.g.; 3. Use the calendar to do the following: - Identify or read the day of the week and the month of the year for a given calendar date. - Identify the day (or month) that comes before or after a given day (or month) - Name, order and count the days in a week and the months in a year, - Identify certain events and when they occur within the year (Christmas, Easter, local festivals, leap years, FIFA world cup etc.); 30 days has September, April, June, and November.; All the rest have 31,; Except for February alone, which has 28 days clear,; and 29 in each leap year.', 360),
('Basic 3', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Length, Mass, Time', 'B3.3.3.3', 'Demonstrate an understanding of time taken by events in days, weeks and months', 'B3.3.3.3.3', 'Relate the number of seconds to a minute, minutes to an hour and days to a month in a problem-solving context', 'E.g.; 1. Develop understanding of the 60 seconds one minute; relationship between seconds, 60 minutes one hour; minutes, hours, days and months. Ask 24 hours one day; learners to say the rhyme on units of 7 days one week time (in the box) 52 weeks one year; 12 months one year E.g.; 2. Solving problems requiring an understanding of number of seconds in a minute, the number of minutes in an hour and the number of days in a month', 370),
('Basic 3', 'Mathematics', 'maths', 'Data', 'Data Collection, Organisation, Presentation, Interpretation and Analysis', 'B3.4.1.1', 'Collect first-hand data and organise it using tallies, checkmarks, charts, lists or line plots to answer and pose questions', 'B3.4.1.1.1', 'Gather and record Data', 'E.g.; 1. Use tallies, checkmarks, charts, lists or tables to collect and organize data to answer a question E.g.; 2. Use tallies, checkmarks, charts, lists or tables to answer questions, and justify the answers, based on the organised data', 380),
('Basic 3', 'Mathematics', 'maths', 'Data', 'Data Collection, Organisation, Presentation, Interpretation and Analysis', 'B3.4.1.2', 'Construct and interpret concrete graphs and pictographs to solve problems', 'B3.4.1.2.1', 'Draw and interpret concrete graphs and pictographs to solve problems', 'E.g.; 1. Identify common features of bar graphs that use one-to-many correspondence and use that understanding to create concrete graphs or pictographs, complete with title, labeled axes, key or legend, to represent data collected (up to 3 categories of data) E.g.; 2. Using a one-to-many correspondence solve simple problems (how many altogether, comparing, or take apart problems) requiring interpretation of one-to- many bar graphs (up to 3 categories of data)', 390),
('Basic 3', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'Personal Safety in the Community', 'B3.1.2.1', 'Identify ways of ensuring environmental safety', 'B3.1.2.1.1', 'Demonstrate ways to care for the environment', 'Use questions and answers for learners to explain the environment.; Using Think-Pair-Share, let learners talk about ways of caring for the environment through: tree planting, proper disposal of waste, legal mining, clean-up exercises, avoiding environmental pollution, etc.; Let learners organise and do clean-up exercises in the school environment.; Let learners draw and colour activities of caring for the environment.; Guide learners in groups to do a project on: clearing a rubbish dump, planting trees, checking erosion, clearing choked gutters, etc.; Let learners present their work in class for appreciation and discussion.', 10),
('Basic 3', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'The Purpose of God’s Creation', 'B3.1.3.1', 'Explain the purpose of God’s creation', 'B3.1.3.1.1', 'Explain the purpose of God’s creation of humankind', 'Discuss with learners the creation of humankind. -Who were the first people God created? -Who was created first?; Let learners tell creation stories from the three religious groups in Ghana.; Explain why God created human beings: to take care of other creatures to worship and serve Him, etc.', 20),
('Basic 3', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'The Purpose of God’s Creation', 'B3.1.3.1', 'Explain the purpose of God’s creation', 'B3.1.3.1.2', 'Give reasons for protecting God’s creation', 'Lead learners to think-pair-share on why we should protect God’s creation: - to preserve creation for generations, - it is a command from God, - our survival depends on other creation: food, medicine, shelter, air, etc. and - it is service to God and humankind.', 30),
('Basic 3', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'The Purpose of God’s Creation', 'B3.1.3.1', 'Explain the purpose of God’s creation', 'B3.1.3.1.3', 'Explain the need for good relationship among people of different ethnic groups', 'Lead learners to talk about good relationships.; Let learners talk about things that promote good relationships: comportment, respect, love, obedience, humility, friendliness, etc.; Let learners identify their friends and say things they like about them.; Let learners discuss in groups, the need for good relationships.; Let groups present their findings to the class: we are people created by God to ensure peace and unity, companionship, teamwork, caring for one another, etc.; Let learners dramatise behaviours that show good relationships.', 40),
('Basic 3', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Religious Worship in the Three Major Religions in Ghana', 'B3.2.1.1', 'Appreciate the importance of religious worship', 'B3.2.1.1.1', 'Name the sacred scriptures of the three major religions', 'Guide learners to mention the sacred scriptures: The Holy Bible (Christianity), The Holy Qur’an, Hadith (Islam), Sacred Myths, parables and taboos (Traditional Religion), etc.; Let learners in groups, talk about the Holy Scriptures and which religion each belongs to.; Guide learners to recite simple texts from the scriptures: Al-Fãtihah (Islam), Psalm 23 (Christianity) and Sacred Myths, folktales, parables, etc. (Traditional Religion).; Let learners write simple texts from the sacred scriptures.', 50),
('Basic 3', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Religious Worship in the Three Major Religions in Ghana', 'B3.2.1.1', 'Appreciate the importance of religious worship', 'B3.2.1.1.2', 'Give reasons for studying the sacred scriptures of the three major religions among their followers', 'Let learners talk about the religion they belong to.; Let learners mention the scriptures their religion uses.; Discuss the importance of studying the sacred scriptures: - they lead us to God, - they help us to know the Truthfulness about God and the world, - they help us to lead good moral lives, - they give us messages from God, etc.; Let learners recite texts from the scriptures.; Guide learners to talk about the moral lessons from the scriptures.', 60),
('Basic 3', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Festivals in the Three Major Religions', 'B3.2.2.1', 'Explain the importance of religious festivals', 'B3.2.2.1.1', 'Describe how various festivals are celebrated', 'Let learners mention religious festivals they have witnessed or heard about: - Islam-Eid-ul-Fitr, Eid-ul-Adha, etc. - Christianity-Easter, Christmas, Ash Wednesday, Pentecost Day, etc. - Traditional-Aboakyer, Hogbetsotso, Adae, Fetu AfahyƐ, Feok, etc.; Let learners, in groups, describe how various festivals are celebrated.; Let learners dramatise activities that take place during the festivals.; Let learners draw scenes from festivals: durbar of chiefs, drumming and dancing, merry-making, etc.', 70),
('Basic 3', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Festivals in the Three Major Religions', 'B3.2.2.1', 'Explain the importance of religious festivals', 'B3.2.2.1.2', 'Demonstrate the importance of religious festivals', 'Show pictures and videos of religious festivals.; Using pictures and or video clips etc., let learners demonstrate how festivals are celebrated.; Let learners talk about the scenes in the pictures or the videos.; Guide learners to narrate the events in the festivals they have participated in.; In groups, guide learners to discuss the importance of festivals: to remember key events in the past, reconciliation, renewal of faith, thanksgiving, etc.; Let learners draw scenes they saw during the festival they witnessed.', 80),
('Basic 3', 'Religious & Moral Education', 'rme', 'Religious Leaders', 'Early Life of the Leaders of the three Major Religions', 'B3.3.1.1', 'Narrate the youthful life stories of the leaders of the major religions', 'B3.3.1.1.1', 'Describe the youthful lives of the leaders of the three major religions in Ghana', 'Guide learners to talk about the youthful lives of the religious leaders: - The Lord Jesus Christ - The Holy Prophet Muhammad (S.A.W) - A Traditional Religious Leader; In groups, let learners talk about the occupations of the religious leaders. - The Lord Jesus Christ as a carpenter, - The Holy Prophet Muhammad (S.A.W) as a businessman - A Traditional Religious Leader, e. g. Egya Ahor as a farmer.; In groups, let learners write short paragraphs on the occupational lives of the religious leaders and present to class for discussion.', 90),
('Basic 3', 'Religious & Moral Education', 'rme', 'Religious Leaders', 'Early Life of the Leaders of the three Major Religions', 'B3.3.1.1', 'Narrate the youthful life stories of the leaders of the major religions', 'B3.3.1.1.2', 'Identify and explain the moral lessons of the youthful life of the religious leaders', 'Discuss with learners the moral lessons of the youthful lives of the religious leaders: piety, honesty, sacrifice, patience, hard work, courage, perseverance, etc.; Guide learners to talk about how they can apply the moral lessons they learnt from the lives of the religious leaders in their daily lives.; Let learners dramatise the moral lives of the religious leaders.', 100),
('Basic 3', 'Religious & Moral Education', 'rme', 'The Family and the Community', 'Roles and Relationships', 'B3.4.1.1', 'Appreciate the role of the family and the community in their relationship with God', 'B3.4.1.1.1', 'Discuss God’s promises to humankind', 'Lead learners to identify the promises God made to humankind: the call of Abraham (Ibrahim)-God promised him with eternal life, the call of Moses (Musa), etc.; In groups, let learners discuss the calls of Abraham (Ibrahim) and Moses (Musa).; Let learners present their work to class for discussion.; Let learners role-play the call of Moses (Musa).', 110),
('Basic 3', 'Religious & Moral Education', 'rme', 'The Family and the Community', 'Roles and Relationships', 'B3.4.1.1', 'Appreciate the role of the family and the community in their relationship with God', 'B3.4.1.1.2', 'Identify the benefits of responding to God’s call', 'Discuss with learners the ways we respond to God’s call: - Prayer, - service to humankind, - caring for the environment, - helping the needy (charity), etc.; In groups, let learners mention the benefits of responding to God’s call: -blessings from God, -drawing closer to God, - long life, - prosperity, -eternal life, etc.; Guide learners to discuss the benefits of responding to God’s call.; Let learners in their groups, write four benefits of responding to God’s call and present their works for class discussion.', 120),
('Basic 3', 'Religious & Moral Education', 'rme', 'The Family and the Community', 'Roles and Relationships', 'B3.4.1.1', 'Appreciate the role of the family and the community in their relationship with God', 'B3.4.1.1.3', 'Identify moral lessons learnt from responding to God’s call', 'Let learners discuss moral lessons derived from responding to God’s call.; Lead learners to mention the moral lessons they learnt from responding to God’s call: obedience, respect, sacrifice, commitment, reverence for God, humility, etc.; Using the sacred scriptures, let learners dramatise moral activities such as humility, obedience, reverence, commitment, respect, honouring promises, etc.', 130),
('Basic 3', 'Religious & Moral Education', 'rme', 'The Family and the Community', 'Personal Safety in the Community', 'B3.4.2.1', 'Explain the role of the family members in living safely with each other', 'B3.4.2.1.1', 'Explain the need to live in harmony with one another', 'Have learners mention ways of living in harmony with one another.; Discuss the need to live in harmony with one another: to promote peace and unity, law and order, growth and development, etc.; In a Think-Pair-Share session, let learners talk about attitudes and behaviours that promote harmonious living at home, school, community, etc.', 140),
('Basic 3', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B3.1.1.1', 'Show understanding of the physical features and life processes of living things and use this understanding to classify them', 'B3.1.1.1.1', 'Classify living things into plants and animals by their life processes', 'Learners watch pictures and videos on living things; Learners collect and display cut-out pictures or flash cards of plants and animals; Learners sort the living things into plants and animals through an activity.; Draw two large circles and let learners place living things into different circles for plants and animals based on their life processes.; Produce more materials for different activities', 10),
('Basic 3', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B3.1.2.1', 'Recognise materials as important resources for providing human needs', 'B3.1.2.1.1', 'Identify the uses of everyday materials and link the uses to their properties', 'Show learners pictures and videos of common materials e.g. wood, plastics, paper, metals, leather, cotton, etc.; Learners collect everyday materials in their environment e.g. wood, plastics, paper, metals, leather, cotton, etc. and bring them to class.; Learners use think-pair-share to discuss the uses of the materials collected.; Brainstorm with learners to come out with the uses of the materials in relation to their properties, e.g. metals are used for making car bodies because they are hard, plastics are used for making bottles, buckets, bowls because they can be moulded into different shapes; Engage learners in an activity to match some products such as buckets, cups, books, tables with their material sources such as metals, clay, glass, wood, plastics.; Provide a lot of materials for the learners to do more activities.', 20),
('Basic 3', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B3.1.2.1', 'Recognise materials as important resources for providing human needs', 'B3.1.2.1.2', 'Demonstrate understanding that an object is made of one or more materials', 'Display objects such as computer, football, clothes, mobile phone, pencils etc.; Provide materials such as glass, plastics, wood, metals etc.; Assist learners to identify that an object such as computer is made up of materials such as plastics, glass and metals.; Engage learners to give examples of objects and the materials used to make them; Do more activities with learners to build the concepts of objects and materials.', 30),
('Basic 3', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B3.1.2.2', 'Understand mixtures, types, formation, uses and ways of separating them into their components', 'B3.1.2.2.1', 'Describe a solid-liquid mixture and explain how to separate the components', 'Provide solid and liquid substances e.g. water, sand, iron filings, powdered charcoal etc.; Learners in their groups, add sand to water or any solid to a liquid.; Learners observe and come out with their findings on the components of the mixture.; Learners describe solid - liquid mixtures and how the components can be separated.; Learners in groups, discuss the uses of solid-liquid mixtures in everyday life. Project: Assist learners to separate solid-liquid mixtures, e.g. gari and water, sand and water, salt solution.', 40),
('Basic 3', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B3.1.2.3', 'Know that substances can exist in different physical state (solid, liquid, Gas). Many substances can be changed from one state to another by heating or cooling', 'B3.1.2.3.1', 'Explain how substances change state between solid, liquid and gas', 'Learners watch pictures and videos of solid, liquid and gaseous substances.; Provide learners with solid and liquid substances such as shea butter, water, candle wax, ice; Learners identify the physical states of the materials provided.; Heat water for learners to observe how it changes to gas and cools down from gas to water (from liquid to gas and back to liquid).; Engage learners to melt Shea butter and candle wax and let them observe how they change from solid to liquid and liquid to solid.; Elaborate on their ideas to explain how substances change state. Note: No new substance is formed from the activities. Share with learners, some everyday occurrences in which no new thing is formed.', 50),
('Basic 3', 'Science', 'science', 'Cycles', 'Earth Science', 'B3.2.1.1', 'Recognise that some events in our environment occur recurrently', 'B3.2.1.1.1', 'Describe some cyclic events like day and night, wet and dry seasons and their intervals/periods', 'Prior to the lesson, task learners to find-out some different cyclic events from their homes (This should include day and night, wet and dry seasons, going to school, Independence Day celebrations, cultivation of crops [e.g. maize] and others).; Learners mention the importance of some cyclic events; Guide learners to identify some activities associated with each event; Learners draw any of the cycles e.g. day and night, wet and dry seasons', 60),
('Basic 3', 'Science', 'science', 'Cycles', 'Earth Science', 'B3.2.1.2', 'Recognise the relationship between the Earth and the Sun', 'B3.2.1.2.1', 'Know the importance of the sun to the earth', 'Begin by discussing with learners the role of the sun and its importance to life on earth.; Ask the following questions: (a) what is the sun? (b) What are some of the ways through which the earth benefits from the sun?; Learners perform outdoor activities to illustrate the importance of the sun.; Guide learners to know other major uses of the sun to the earth.; Learners outline everyday uses of the sun.; Evaluate the lesson by asking learners to draw a picture showing one benefit of the sun to life on earth (drying of clothes).', 70),
('Basic 3', 'Science', 'science', 'Cycles', 'Earth Science', 'B3.2.1.3', 'Show understanding of the roles of condensation, evaporation, transpiration and precipitation in the hydrological (water) cycle', 'B3.2.1.3.1', 'Identify the types of precipitation (rain, snow, hail, sleet) and describe the differences among them', 'Explore the previous knowledge of learners on this topic, e.g., learners know of iced water, ‘ice block’ and rainfall.; Provide learners with cut-out pictures or videos of the other forms of precipitation (snow, hail, sleet, these may be foreign to them.; Learners examine the pictures and communicate their ideas on the different types of precipitation.; Guide learners to explain each term. For example: Sleet is ice pellets that fall from clouds.; Assist learners to build vocabulary on precipitation.; With the aid of flashcards, learners work in groups to match pictures showing different types of precipitation with their correct names.; Learners draw a picture showing a rainy day. Project: Assist learners to undertake an activity to create artificial rain in the school.', 80),
('Basic 3', 'Science', 'science', 'Cycles', 'Earth Science', 'B3.2.1.4', 'Recognise water and air as important natural resources', 'B3.2.1.4.1', 'Identify things that make water impure', 'Provide learners with cut-out pictures showing how water is polluted. This should include leakages, flooding during rainy season which carries waste deposits into water bodies, Industrial waste dumped into water, mining, littering, pesticides application, fertilizer application, house hold chemicals, improper disposal of animal wastes.; In groups, learners observe the pictures and communicate their ideas on what makes water impure.; Take learners on a trip to observe littered parts of the community to identify things that make water impure.; Ask learners what will happen if they drink impure water.', 90),
('Basic 3', 'Science', 'science', 'Cycles', 'Earth Science', 'B3.2.1.4', 'Recognise water and air as important natural resources', 'B3.2.1.4.2', 'Describe the properties of air', 'Learners answer the following questions: What is air? Where does air come from? Can you see and touch air? What shows that there is air present in this classroom?; Perform a simple demonstration on the properties of air, e.g. air has mass, occupies space, made up of more than one gas, pulls and pushes objects.; Learners demonstrate how to make more air enter their classrooms in groups.; Let each group present their findings.', 100),
('Basic 3', 'Science', 'science', 'Cycles', 'Life Cycles of Organisms', 'B3.2.2.1', 'Demonstrate understanding of life cycle of a plant', 'B3.2.2.1.2', 'Observe the germination of maize and bean seeds', 'Begin this activity by asking learners to predict whether it is possible for bean and maize seeds to germinate/sprout in water without soil.; Place learners into groups and give each group two transparent glasses or plastic containers (labeled A and B), cotton wool, water and viable maize and bean seeds.; Learners pack container A with the cotton wool and push one of each of the different seeds through the side of the container but not to touch the bottom.; Guide learners to pour a little water to soak the cotton wool. The set-up is left to stand for one week while keeping the cotton wool always wet.; Guide learners to prepare container B using the same method but with a dry cotton wool.; Learners observe the set-up critically and record whatever they see.; Challenge learners with the question: What made the seeds germinate in set-up A?', 110),
('Basic 3', 'Science', 'science', 'Systems', 'The Human Body Systems', 'B3.3.1.1', 'Recognise that different parts of the human body work interdependently to perform a specific function', 'B3.3.1.1.1', 'Explain that the external parts of the human body work interdependently to perform a function', 'Engage pupils in songs on the various parts of the body, e.g. head, shoulders, knees and toes, show me your head, my head, my shoulders my knees, my toes.; Learners brainstorm on how the various parts of the human body support each other to perform various functions, e.g. assuming a dog is barking towards you, how do the eyes, ears, feet help you to recognise danger and escape?; Learners engage in various activities (skipping), playing football and explain how the various parts of the body contribute to undertake the activity successfully. NB: The key lesson for learners is to appreciate the fact that every part of the body is important and must be taken care of.', 120),
('Basic 3', 'Science', 'science', 'Systems', 'The Solar System', 'B3.3.2.1', 'Show understanding of the orderliness of the sun, planets and satellites in the solar system as well as the important role of the sun in the existence of the solar system', 'B3.3.2.1.1', 'Know the sun, earth and moon as parts of the solar system', 'Show learners pictures, charts or drawings of parts of the solar system containing the sun, earth and moon.; Engage learners in a recital of the poem “I see the moon, and the moon sees me”.; Assist learners to identify the sun, moon and earth in the pictures.; Guide learners to mention the uses of the sun and moon.; Assist learners to know that the earth moves around the sun, and the moon moves around the earth.; Engage learners in an activity to role play the movement of the earth around the sun, and the moon around the earth; Learners in groups make a model of the solar system showing only the sun, earth and moon.', 130),
('Basic 3', 'Science', 'science', 'Systems', 'Ecosystem', 'B3.3.3.1', 'Show understanding and appreciation of the interactions and interdependencies of organisms in an ecosystem', 'B3.3.3.1.1', 'Identify organisms in a habitat and describe why they live in a particular place', 'Show pictures, videos and drawings of organisms in their various homes (habitats).; Take learners on a field trip (or a tour of the school environment) to study about some ecosystems, e. g. (1) Birds and insects on a tree (2) Frogs and fish in a pond/stream (3) Grasshoppers, insects on a grass field (4) Different plant on a farm.; Assist learners to identify some observable features that enable organisms to live successfully in their habitat e.g. tilapia has fins to help it swim in a pond. Birds have wings to help them.; Guide learners to discuss the following: (1) is a frog a fish? (2) Why can’t a fish live on land?; Learners plan, design and draw posters showing organisms in their natural homes.', 140),
('Basic 3', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B3.4.1.1', 'Demonstrate understanding of the concept of energy, its various forms and sources and the ways in which it can be transformed and conserved', 'B3.4.1.1.1', 'Know that light is a form of energy', 'Ask learners to talk about light and where light comes from.; Engage learners to do the following activities: closing and opening the windows and doors of their classroom, switching on torch or lighting a candle to look for an object in a dark room, switching on the light in the classroom etc.; Learners talk about their experiences based on the activities performed.; Ask learners what will happen if there were no light on the earth.; Assist learners to understand that light is a form of energy that helps us to see.', 150),
('Basic 3', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B3.4.1.2', 'Show understanding of the concept of heat in terms of its sources, effects, importance, and transfer from one medium to another', 'B3.4.1.2.1', 'Know heat as a form of energy and identify some sources of heat', 'Learners rub their palms together vigorously for a while and after that touch their cheeks with their palms.; learners describe how they feel in their palms when they touch their cheeks.; Ask learners to come out with other processes that can generate heat. e.g. lighting of fire, charging a laptop, charging a mobile phone, a bulb/light that is switched on for a long time.; Learners talk about heat as a form of energy.; Assist learners to mention some sources of heat energy. e.g. the sun, a lighted stove, lighted charcoal.', 160),
('Basic 3', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B3.4.1.2', 'Show understanding of the concept of heat in terms of its sources, effects, importance, and transfer from one medium to another', 'B3.4.1.2.2', 'Know everyday uses of heat', 'Review previous lesson on heat energy and ask learners to cite everyday uses of heat energy in the home. e.g. for ironing, food preparation and preservation, heating of water.; Through think-pair-share, ask learners to mention one application of the use of heat energy by the following professions, farmers, nurses, hair dressers, blacksmiths, tailors and seamstresses.; Ask learners to explain why farmers need heat. Precaution: Let learners observe safety whilst dealing with hot substances.', 170),
('Basic 3', 'Science', 'science', 'Forces and Energy', 'Electricity and Electronics', 'B3.4.2.1', 'Demonstrate knowledge of generation of electricity, its transmission and transformation into other forms of energy', 'B3.4.2.1.1', 'Identify different sources of electrical energy', 'Before the lesson, let learners investigate to find-out where they get electricity for their home and school. e.g. Aboadze Thermal Plant, Akosombo and Bui Hydroelectric plants.; Learners listen to a story on the history of how electricity was first produced.; Learners watch a video or look at a poster on how electricity is produced from various sources. E.g. batteries, solar, hydro, thermal and generators.; Learners demonstrate how to produce electricity from simple sources such as dry cells (batteries) to light a torch or a lamp.; Ask learners to discuss the sources of the electricity they use at home', 180),
('Basic 3', 'Science', 'science', 'Forces and Energy', 'Forces and Movement', 'B3.4.3.1', 'Know that movement is caused by applied forces due to the release of stored energy', 'B3.4.3.1.1', 'Explain force and demonstrate how it causes movement', 'Review previous lesson on forces and their effects with learners from B2.; Ask learners the following questions: What is force? How is force described? What forces do you observe in everyday life?; Learners engage in simple demonstrations on how forces cause movement. (1) Rubbing pens in the hair and using it to pick pieces of paper. (2) Using a magnet to attract iron nails or pins. (3) Throwing stones into water in a bucket will cause the water to shake. (4) Push a toy car down on the floor.', 190),
('Basic 3', 'Science', 'science', 'Forces and Energy', 'Forces and Movement', 'B3.4.3.2', 'Recognise some simple machines used for making work easier, analyse their advantages and know their uses. e.g. levers, inclined planes and pulleys', 'B3.4.3.2.1', 'Demonstrate how to maintain and care for simple machines', 'Assemble simple machines commonly used in the community such as a pair of scissors, knife, bottle opener, tin cutter, and hammer.; Learners identify the simple machines provided and talk about their uses.; Engage learners to mention how simple machines are maintained and stored in their homes.; Assist learners to undertake some basic maintenance practices such as oiling, removing dirt and greasing, using them for the correct purpose, keeping them safe from water, etc.', 200),
('Basic 3', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B3.5.1.1', 'Recognise the importance of personal hygiene', 'B3.5.1.1.1', 'Describe ways of keeping the environment clean', 'Provide samples of common cleaning equipment such as brooms, mops, dusters and detergents; Begin by asking learners this question: What do you do to keep the home and school clean?; Learners brainstorm in groups to come out with the different ways of keeping the home and school clean; Learners present their ideas to class and compose a song on cleanliness; Present learners’ ideas on the writing board and reshape learners’ ideas by providing more details on different ways of keeping the environment. E.g. sweeping, weeding, scrubbing, etc.; Learners draw pictures showing ways of keeping the environment clean; Engage learners in an activity to clean selected parts of the school environment NB: Learners must use nose masks when sweeping or dusting.', 210),
('Basic 3', 'Science', 'science', 'Humans and the Environment', 'Diseases', 'B3.5.2.1', 'Know common diseases of humans, causes, symptoms, effects and prevention', 'B3.5.2.1.1', 'Know how common skin diseases can be prevented', 'Ask learners to pantomime or act out how they bath and talk about how regular bathing can prevent skin diseases.; Learners watch pictures and videos on common skin diseases and their prevention.; Learners engaged to discuss and name some common skin diseases i.e. rashes, eczema, ringworm.; Learners share their personal experiences or stories on getting skin infections.; Discuss how common skin diseases can be prevented and let learners present their answers.; Re-shape learners'' ideas, stressing that it is good to seek medical attention to stop the spread of skin diseases. .', 220),
('Basic 3', 'Science', 'science', 'Humans and the Environment', 'Diseases', 'B3.5.2.1', 'Know common diseases of humans, causes, symptoms, effects and prevention', 'B3.5.2.1.2', 'Explain the term air-borne diseases and give examples', 'Begin the lesson with a song, rhyme or poem on air-borne diseases, e.g. I have a little cough Sir.; Learners in groups name and discuss some common air-borne diseases. e.g. cold, cough, measles, chicken pox and rashes.; Brainstorm with learners to bring out the meaning of the term ‘air-borne disease’; Summarise learners’ ideas and reinforce the concept of air-borne diseases.; Learners in a class discussion, find out the effect of unclean/contaminated air.; Learners investigate the effects of smoking cigarette on the health of a person and communicate their findings.', 230),
('Basic 3', 'Science', 'science', 'Humans and the Environment', 'Science and Industry', 'B3.5.3.2', 'Exhibit knowledge of food processing and preservation', 'B3.5.3.2.1', 'Describe the ways foods get spoiled', 'Learners watch pictures and videos on ways by which food get spoilt.; Demonstrate an activity to show how food gets spoilt. E.g. bread, kenkey fish etc.; Learners in groups to discuss ways by which food gets spoilt.; Engage learners to present their ideas in groups to the whole class.; Tabulate group responses and reshape learners’ ideas.; Ask learners to brainstorm on what will happen if they eat spoilt food.; Learners dramatise or tell a story about a child who ate spoilt food. NB: This indicator should not cover micro-organisms.', 240),
('Basic 3', 'Science', 'science', 'Humans and the Environment', 'Climate Change', 'B3.5.4.1', 'Know that climate change is one of the most important environmental issues facing the world today and is a long-term change in the pattern of average weather of a specific region of the earth', 'B3.5.4.1.1', 'Identify human activities that pollute the atmosphere', 'Learners watch pictures and videos on human activities that pollute the atmosphere.; Teacher explains to learners that “atmosphere” refers to the air around us.; Tell stories or talk about scenarios that pollute the atmosphere i.e. burning of waste and bush, exhaust fumes from moving cars etc.; Introduce a simple game or activity to help learners understand how the atmosphere gets polluted., e.g. smoke from mosquito coils, burning of pieces of paper (Note: this activity must be done outside the classroom) and ask learners to tell where the smoke goes.; Evaluate learners by asking them to talk about other activities that pollute the atmosphere. NB: Teacher should not discuss things about climate doom that will scare the learners.', 250);
